    }
    if (entries.isEmpty) {
      final message =
          'role "$role" has no usable chain entry: ${skipped.join('; ')}';
      // gh-760: degrade, never brick — but only the version-skew shape.
      // Unknown providers (a newer app/CLI wrote the config) throw the
      // dedicated subtype the boot boundary degrades on; known providers
      // missing keys stay a plain ConfigException (loud boot failure).
      throw sawUnknownProvider
          ? UnknownProviderRoleException(message)
          : ConfigException(message);
    }
    return entries;
  }

  ChainEntry? _buildEntry(
    ModelRef ref,
    List<String> skipped, {
    required void Function() onUnknownProvider,
  }) {
    // gh-760 (review): resolve by catalog name AND adapter kind — a roles
    // entry written as a kind (`chatgpt-codex`, exactly what the app
    // writes) is KNOWN to this version and must not be skipped as unknown.
    // honorBuildFilter: roles are a user-facing surface — the filter the
    // old name-only + kind-loop pair applied, now in the one seam.
    final spec = resolveCliProviderSpec(ref.provider, honorBuildFilter: true);
    if (spec == null) {
      // gh-760: degrade, never brick. An entry whose provider no version
      // knows (a config written by a newer app/CLI) skips like a
      // missing-key entry — reported in skippedEntries, never thrown —
      // so the remaining known entries carry the role.
      skipped.add('${ref.label} (unknown provider: ${ref.provider})');
      onUnknownProvider();
      return null;
    }
    final keyBase = _keyBaseName(ref, spec);
    if (keyBase == null) {
      skipped.add(
        '${ref.label} (missing API key: ${_missingKeyHint(ref, spec)})',
      );
      return null;
    }
    final ring = _rings.putIfAbsent(
      keyBase,
      () => ApiKeyRing.fromSecrets(_secrets, keyBase, now: _now)!,
    );
    return ChainEntry(
      // Build from the RESOLVED spec's name: a kind-named ref
      // (`chatgpt-codex`) is not itself a catalog key.
      model: buildCatalogModel(
        spec.name,
        ref.modelId,
        baseUrl: ref.baseUrl,
        contextWindow: ref.contextWindow,
        maxTokens: ref.maxTokens,
        input: ref.input,
        thinkingLevel: ref.thinkingLevel,
        authHeader: ref.authHeader,
      ),
      keyRing: ring,
      streamForKey: (apiKey) {
        final inner = _streamFactory(spec.kind, apiKey);
        return (model, context, {cancelToken}) {
          // An explicit per-call override (the compaction bypass) wins over
          // the resolver's bound session id.
          if (StreamCacheRouting.current != null) {
            return inner(model, context, cancelToken: cancelToken);
          }
          return StreamCacheRouting.runWith(
            () => inner(model, context, cancelToken: cancelToken),
            // Read the mutable field lazily: hosts learn the session id
            // after the resolver (and its chains) were built.
            sessionId: sessionId?.call(),
          );
        };
      },
    );
  }

  /// The key base name for [ref]: its explicit `apiKeyName`, else — for a
  /// chain entry pinned to a CUSTOM endpoint — the endpoint-scoped
  /// `FA_KEY_<HOST>` slot (the same source a manual provider switch
  /// resolves; gh-1000 AC5), else the first of the provider's env names
  /// present in the secrets snapshot. `null` when no candidate resolves
  /// to a configured key.
  String? _keyBaseName(ModelRef ref, ProviderSpec spec) {
    final explicit = ref.apiKeyName;
    if (explicit != null) {
      return collectKeyStack(_secrets, explicit).isEmpty ? null : explicit;
    }
    final scopedName = _endpointScopedKeyName(ref, spec);
    if (scopedName != null &&
        collectKeyStack(_secrets, scopedName).isNotEmpty) {
      return scopedName;
    }
    for (final candidate in spec.apiKeyEnvNames) {
      if (collectKeyStack(_secrets, candidate).isNotEmpty) return candidate;
    }
    return null;
  }

  /// The endpoint-scoped `FA_KEY_<HOST>` name for a chain entry pinned to
  /// a non-default endpoint, else null. The snapshot carries the slot's
  /// value when the host collected it (the startup snapshot includes
  /// every custom-endpoint slot a roles chain can need — gh-1000).
  String? _endpointScopedKeyName(ModelRef ref, ProviderSpec spec) {
    final baseUrl = ref.baseUrl;
    // Trailing-slash-normalized (the shared sameEndpoint rule): a default
    // endpoint saved with a trailing slash must not mint a bogus scoped
    // slot — one endpoint-equality rule with key_status (round-3 review).
    if (baseUrl == null || sameEndpoint(baseUrl, spec.defaultBaseUrl)) {
      return null;
    }
    return CustomProviderRegistry.keyNameFor(baseUrl);
  }

  /// The missing-key hint for [ref]'s skip reason: an explicitly pinned
  /// `apiKeyName` names THAT slot (the only name that would resolve it —
  /// the endpoint-scoped default would be wrong-slot guidance, gh-1000
  /// AC2), a custom endpoint names its `/key set` fix (the catalog env
  /// name would point at the DEFAULT endpoint — the wrong slot, gh-1000
  /// AC2/AC5), a default endpoint names its env var.
  String _missingKeyHint(ModelRef ref, ProviderSpec spec) {
    final explicit = ref.apiKeyName;
    if (explicit != null) {
      return '/key set $explicit <value>';
    }
    final scopedName = _endpointScopedKeyName(ref, spec);
    if (scopedName != null) {
      return '/key set $scopedName <value>';
    }
    return 'set ${spec.apiKeyEnvNames.first}';
  }

  /// The cached [FallbackStreamFunction] for [role] (entry cooldowns and
  /// chain position persist across runs — session state).
  FallbackStreamFunction streamForRole(String role) {
    return _wrappers.putIfAbsent(role, () {
      final entries = chainFor(role);
      if (entries == null) {
        throw ConfigException('role "$role" is not configured');
      }
      return FallbackStreamFunction(
        entries: entries,
        policy: config.retry,
        onNotice: (notice) => onNotice?.call(notice),
        now: _now,
        jitterFraction: jitterFraction,
        sleeper: sleeper,
      );
    });
  }

  /// Resolves [role] to its current model and stream function, or `null`
  /// when the role (and the inherited `default`) is unconfigured.
  ({Model model, StreamFunction stream})? resolveRole(String role) {
    if (config.chainFor(role, cwd: cwd, homeDir: homeDir) == null) {
      return null;
    }
    final wrapper = streamForRole(role);
    return (model: wrapper.currentModel, stream: wrapper.call);
  }

  /// Points [agent] at [role]'s model and fallback stream for subsequent
  /// runs (the agent's role for a run; hosts use `default` for user turns).
  void applyToAgent(Agent agent, {String role = defaultModelRole}) {
    final wrapper = streamForRole(role);
    agent.streamFunction = wrapper.call;
    agent.state.model = wrapper.currentModel;
  }

  /// Replaces the `default` role's chain (runtime `/model <id>` switch);
  /// the new chain takes effect on the next run.
  void setDefaultChain(List<ModelRef> chain) {
    setRoleChain(defaultModelRole, chain);
  }

  /// Replaces [role]'s chain (the settings-hub agent-models flow); the new
  /// chain takes effect on the next run.
  void setRoleChain(String role, List<ModelRef> chain) {
    if (chain.isEmpty) {
      throw ArgumentError.value(
        chain,
        'chain',
        'a role needs at least one chain entry',
      );
    }
    config = ModelRolesConfig(
      roles: {...config.roles, role: chain},
      pathOverrides: config.pathOverrides,
      retry: config.retry,
    );
    _wrappers.remove(role);
  }

  /// Replaces the retry policy (the settings-hub resilience flow, issue
  /// #393). Every role's cached wrapper captured the old policy at
  /// construction, so ALL of them are rebuilt — the new knobs govern the
  /// next run's retry chain; a run already streaming keeps the old one.
  void setRetryPolicy(ModelRolesRetryPolicy policy) {
    config = ModelRolesConfig(
      roles: config.roles,
      pathOverrides: config.pathOverrides,
      retry: policy,
    );
    _wrappers.clear();
  }

  /// "use the main model" escape of the settings-hub agent-models flow).
  void clearRoleChain(String role) {
    if (role == defaultModelRole) {
      throw ArgumentError.value(role, 'role', 'the default role is required');
    }
    if (!config.roles.containsKey(role)) return;
    final roles = {...config.roles}..remove(role);
    config = ModelRolesConfig(
      roles: roles,
      pathOverrides: config.pathOverrides,
      retry: config.retry,
    );
    _wrappers.remove(role);
  }

  /// Renders the roles overview for `/model`: each configured role with its
  /// chain, the active entry marked (`*`), cooling-down entries annotated,
  /// and skipped entries listed.
  String describeRoles() {
    final buffer = StringBuffer();
    for (final role in modelRoleIds) {
      final chain = config.chainFor(role, cwd: cwd, homeDir: homeDir);
      if (chain == null) continue;
      _describeRole(buffer, role, chain);
    }
    return buffer.toString().trimRight();
  }

  /// Renders one role block: the header line (with the inherit-default
  /// annotation), its chain entries, and its skipped entries.
  void _describeRole(StringBuffer buffer, String role, List<ModelRef> chain) {
    final wrapper = _wrappers[role];
    final inherited =
        role != defaultModelRole && !config.roles.containsKey(role);
    buffer.write('$role${inherited ? ' (inherits default)' : ''}:');
    _describeChainEntries(buffer, chain, wrapper);
    final skipped = skippedEntries[role];
    if (skipped != null && skipped.isNotEmpty) {
      buffer.write('\n  skipped: ${skipped.join('; ')}');
    }
    buffer.write('\n');
  }

  /// Renders [chain]'s entries, marking the wrapper's active entry (`*`)
  /// and annotating cooling-down entries.
  void _describeChainEntries(
    StringBuffer buffer,
    List<ModelRef> chain,
    FallbackStreamFunction? wrapper,
  ) {
    for (var i = 0; i < chain.length; i++) {
      final active = wrapper != null && wrapper.activeIndex == i;
      final cooldown = wrapper?.cooldownRemaining(i);
      buffer.write(
        '\n  ${active ? '*' : ' '} ${chain[i].label}'
        '${cooldown == null ? '' : ' (cooldown ${cooldown.inSeconds}s)'}',
      );
    }
  }
}

/// The rate-limit fallback engine: a [StreamFunction] wrapper that walks an
/// ordered chain of models, rotating API keys and failing over on
/// rate-limit/quota errors — mid-turn take-over without silent degradation.
///
/// Ported (reduced) from oh-my-pi's non-compaction retry policy
/// (`docs/non-compaction-retry-policy.md`, `agent-session.ts`
/// `#handleRetryableError`). Mapping and deliberate divergences:
///
/// - omp retries at the session layer (`agent_end` → strip error →
///   `continue()`); this wrapper retries **inside one provider call** (a
///   turn), which keeps the agent loop untouched and gives every
///   [StreamFunction] consumer (agent turns, compaction summaries, plugins)
///   the same policy.
/// - omp's trigger set is broad (overloads, 5xx, network failures, stale
///   replays, refusals). Rate-limit/quota failures ([isRateLimitOrQuota])
///   trigger rotation/fallback, and transient transport failures
///   ([isTransientTransportError] — dropped connections, DNS/TLS, gateway
///   5xx) trigger in-place retries with the same backoff budget; everything
///   else is forwarded verbatim. Context overflow is explicitly excluded —
///   it belongs to the compaction path, same boundary as omp.
/// - omp's observable-output guard is kept: a stream that already emitted
///   content is never silently replayed; its failure stands.
/// - omp emits session events (`auto_retry_start`, `retry_fallback_applied`).
///   Our event types (`AssistantMessageEvent`, `AgentEvent`) are sealed
///   hierarchies in core libraries that this layer cannot extend, so the
///   no-silent-degrade note surfaces through the [FallbackNotice] listener
///   callback instead — hosts render it (the CLI prints a `[roles]` line).
///   The produced [AssistantMessage] itself always carries the fallback
///   model's identity (`provider`/`model`), so the transcript also shows
///   which model actually answered.
library;

import 'dart:async';
import 'dart:math';

import '../agent/agent_loop.dart';
import '../cancel_token.dart';
import '../context.dart';
import '../event_stream.dart';
import '../model.dart';
import '../overflow.dart';
import '../providers/quota.dart';
// Issue #1168: the resumed-exhaustion terminal signature - a transport
// chain that spent its budget mid-answer must not be re-classified as
// retryable (the ladder would rewrap it as "not retried", false after
// the chain's own attempts) nor retried again.
import '../providers/transient_retry_stream.dart'
    show isTransientExhaustionStory;
import '../types.dart';
import 'key_rotation.dart';
import 'roles_config.dart';

/// Patterns classifying a provider error as rate-limit/quota (retryable by
/// rotation/fallback). Kept text-based like omp's classifier
/// (`isUsageLimitError` + transient patterns); structured signal comes from
/// the parsed `Retry-After` on [ErrorEvent.retryAfter].
final _rateLimitPatterns = [
  RegExp(r'rate.?limit', caseSensitive: false),
  RegExp(r'too many requests', caseSensitive: false),
  RegExp(r'\b429\b'),
  RegExp(r'quota', caseSensitive: false),
  RegExp(r'resource.{0,30}exhausted', caseSensitive: false),
  RegExp(r'usage.?limit', caseSensitive: false),
  RegExp(r'throttl', caseSensitive: false),
];

/// Whether [message] is a rate-limit/quota failure the chain may retry.
///
/// Requires an error stop with a message, excludes context overflow (that
/// failure class belongs to compaction, mirroring omp's hard exclusion), and
/// then matches the rate-limit pattern set — HTTP 429 wordings, provider
/// quota messages (OpenAI `insufficient_quota`, Google "Resource has been
/// exhausted", Bedrock throttling) included. [retryAfter] is the structured
/// hint parsed from the `Retry-After` header; its presence alone does not
/// classify (a 500 may carry it).
bool isRateLimitOrQuota(AssistantMessage message, {Duration? retryAfter}) {
  if (message.stopReason != StopReason.error) return false;
  final text = message.errorMessage;
  if (text == null || text.isEmpty) return false;
  if (isContextOverflow(message)) return false;
  return _rateLimitPatterns.any((pattern) => pattern.hasMatch(text));
}

/// Patterns classifying a provider error as a transient transport failure:
/// dropped/refused/reset connections, DNS and TLS handshake failures, and
/// the 5xx server family (500 internal errors, 502/503/504 gateways —
/// production gateways fail with one-off "500: Internal network failure,
/// please try again later", which must retry, not kill the turn).
/// Rate-limit wordings are deliberately excluded — they follow the rotation
/// policy instead.
final _transportPatterns = [
  RegExp(r'connection closed', caseSensitive: false),
  RegExp(r'connection reset', caseSensitive: false),
  RegExp(r'connection refused', caseSensitive: false),
  RegExp(r'connection aborted', caseSensitive: false),
  RegExp(r'connection terminated', caseSensitive: false),
  RegExp(r'connection (attempt )?timed? ?out', caseSensitive: false),
  RegExp(r'socket ?exception', caseSensitive: false),
  RegExp(r'client ?exception', caseSensitive: false),
  RegExp(r'failed host lookup', caseSensitive: false),
  RegExp(r'network is unreachable', caseSensitive: false),
  RegExp(r'no route to host', caseSensitive: false),
  RegExp(r'handshake (failed|error|terminated)', caseSensitive: false),
  RegExp(r'broken pipe', caseSensitive: false),
  RegExp(r'\b50[0234]\b'),
  RegExp(r'bad gateway', caseSensitive: false),
  RegExp(r'service unavailable', caseSensitive: false),
  RegExp(r'gateway time-?out', caseSensitive: false),
  RegExp(r'internal (server|network) error', caseSensitive: false),
  RegExp(r'internal network failure', caseSensitive: false),
  RegExp(r'please try again later', caseSensitive: false),
  // Provider watchdogs surface wedged endpoints as Dart TimeoutExceptions
  // ("TimeoutException after 0:03:00.000000: Future not completed") or
  // plain request-timeout wordings — always retryable.
  RegExp(r'timeout ?exception', caseSensitive: false),
  RegExp(r'request (attempt )?timed? ?out', caseSensitive: false),
  // Truncation class (issue #312): a stream that closes without a
  // finish_reason and without committed content is a cut transport.
  RegExp(r'stream ended without finish_reason'),
];

/// Whether [message] is a transient transport failure the chain may retry
/// in place: the endpoint (or the network path to it) dropped, so rotating
/// credentials is pointless — the same entry is retried with backoff, then
/// the chain fails over to the next model. Context overflow and rate limits
/// are excluded (their own policies own them).
bool isTransientTransportError(AssistantMessage message) {
  if (message.stopReason != StopReason.error) return false;
  final text = message.errorMessage;
  if (text == null || text.isEmpty) return false;
  if (isContextOverflow(message)) return false;
  if (isTransientExhaustionStory(text)) return false;
  if (_rateLimitPatterns.any((pattern) => pattern.hasMatch(text))) {
    return false;
  }
  return _transportPatterns.any((pattern) => pattern.hasMatch(text));
}

/// What the wrapper is about to do after a rate-limit failure.
enum FallbackNoticeKind {
  /// Sleeping, then retrying the same chain entry (omp `auto_retry_start`).
  retry,

  /// Switching to another API key of the same entry (omp credential switch).
  keyRotation,

  /// Taking the run over with the next chain entry (omp
  /// `retry_fallback_applied`).
  modelFallback,

  /// Re-trying the same entry after a transient transport failure (a
  /// dropped connection, DNS/TLS failure, or a 502/503/504) — no key
  /// rotation: the endpoint dropped, not the credential.
  transportRetry,
}

/// Why a queue entry died (issue #418 UT-kind-labeling): the exact string
/// a switch event carries. Ordered by classification precedence.
enum QueueDeathKind {
  /// HTTP 429 / quota exhaustion (cooldown follows `Retry-After`).
  quota('quota'),

  /// HTTP 401/403 — the key is dead; advance immediately, no cooldown.
  auth('auth'),

  /// Connect refused / reset / DNS / dropped connection.
  network('network'),

  /// Provider watchdog death (connect or stream-idle timeout).
  timeout('timeout'),

  /// Malformed stream: bad SSE line, non-JSON delta, abrupt close without
  /// a terminal event, 200-with-empty-stream (silent-empty-provider trap).
  malformed('malformed'),

  /// 5xx after the retry ladder is spent.
  fivexx('5xx'),

  /// Unknown/aborted wire finish_reason after transient retries (#312).
  finishReason('finish_reason');

  const QueueDeathKind(this.label);

  /// The exact string switch events and health badges carry.
  final String label;
}

/// One classified provider death: what killed the entry and how the chain
/// should react.
final class QueueDeath {
  /// Creates the classification.
  const QueueDeath({required this.kind, this.cooldown, this.immediate = false});

  /// The death kind (the switch event's label).
  final QueueDeathKind kind;

  /// The base cooldown for the dead entry; null derives from the event's
  /// `Retry-After` (quota) or the policy backoff (everything else).
  final Duration? cooldown;

  /// Whether the chain skips the retry ladder and advances at once
  /// (auth — retrying a dead key is wasted latency).
  final bool immediate;
}

/// Classifies an error event into a queue death, or null when the chain
/// must NOT advance (content_filter family, user abort) and the error
/// surfaces verbatim (issue #418: advance on ANY provider death, never on
/// safety stops).
typedef QueueDeathClassifier = QueueDeath? Function(ErrorEvent event);

/// The sticky RAM cursor and per-entry health of a provider-queue-driven
/// [FallbackStreamFunction] (issue #418). Volatile by contract — restart
/// constructs a fresh wrapper and the queue restarts at its head (AC6);
/// nothing ever persists this object.
final class ProviderQueueState {
  /// Per-entry health: cooldown deadline, consecutive failures, and the
  /// last failure's story.
  final _entries = <int, _QueueEntryHealth>{};

  var _currentIndex = 0;

  /// The entry serving requests right now (the sticky cursor).
  int get currentIndex => _currentIndex;

  /// Records a failed attempt on [index]: bumps the consecutive-failure
  /// count and stores the error story. Returns the failure count AFTER
  /// the bump (the cooldown doubling input).
  int recordFailure(int index, QueueDeathKind kind, String errorText) {
    final health = _entries.putIfAbsent(index, _QueueEntryHealth.new);
    health.consecutiveFailures++;
    health.lastError = errorText;
    health.lastErrorKind = kind;
    return health.consecutiveFailures;
  }

  /// Records a served request on [index]: counters and the error story
  /// reset (success heals — AC5).
  void recordSuccess(int index) {
    _entries.remove(index);
    _currentIndex = index;
  }

  /// Mirrors the wrapper's cooldown decision for [index].
  void recordCooldown(int index, DateTime until) {
    _entries.putIfAbsent(index, _QueueEntryHealth.new).cooldownUntil = until;
  }

  /// Mirrors the wrapper's active entry at call start.
  void recordCurrentIndex(int index) => _currentIndex = index;

  /// Cooldown remaining on [index], or null when healthy.
  Duration? cooldownRemaining(int index, DateTime now) {
    final until = _entries[index]?.cooldownUntil;
    if (until == null) return null;
    if (now.isBefore(until)) return until.difference(now);
    return null;
  }

  /// The entry's consecutive failure count (0 when healthy).
  int consecutiveFailures(int index) =>
      _entries[index]?.consecutiveFailures ?? 0;

  /// The entry's last error text, or null when it never failed.
  String? lastError(int index) => _entries[index]?.lastError;

  /// The entry's last death kind, or null when it never failed.
  QueueDeathKind? lastErrorKind(int index) => _entries[index]?.lastErrorKind;
}

/// Mutable per-entry health of [ProviderQueueState].
final class _QueueEntryHealth {
  DateTime? cooldownUntil;
  var consecutiveFailures = 0;
  String? lastError;
  QueueDeathKind? lastErrorKind;
}

/// The no-silent-degrade note: emitted through the listener callback before
/// every retry/rotation/failover so the degradation is always visible.
final class FallbackNotice {
  /// Creates a notice.
  const FallbackNotice({
    required this.kind,
    required this.fromModel,
    this.toModel,
    this.apiKeyName,
    required this.delay,
    required this.attempt,
    required this.reason,
  });

  /// What happens next.
  final FallbackNoticeKind kind;

  /// The `provider/modelId` that just failed.
  final String fromModel;

  /// The `provider/modelId` taking over (modelFallback only).
  final String? toModel;

  /// The secrets-store name of the key taking over (keyRotation only) — the
  /// name, never the value.
  final String? apiKeyName;

  /// The sleep before the next attempt (zero for key/model switches, per
  /// omp's delay-0-on-switch rule).
  final Duration delay;

  /// 1-based count of rate-limit failures seen in this provider call.
  final int attempt;

  /// The classified failure (truncated provider error text).
  final String reason;

  /// One-line rendering for hosts (the CLI prints it verbatim).
  String describe() {
    final wait = delay == Duration.zero
        ? ''
        : ' in ${(delay.inMilliseconds / 1000).toStringAsFixed(1)}s';
    return switch (kind) {
      FallbackNoticeKind.retry =>
        'rate limited on $fromModel — retrying$wait '
            '(attempt ${attempt + 1})',
      FallbackNoticeKind.keyRotation =>
        'rate limited on $fromModel — rotating API key to $apiKeyName',
      FallbackNoticeKind.modelFallback =>
        'rate limited on $fromModel — falling back to $toModel',
      FallbackNoticeKind.transportRetry =>
        'connection lost on $fromModel — retrying$wait '
            '(attempt ${attempt + 1})',
    };
  }
}

/// One entry of a [FallbackStreamFunction]'s chain: the model to call, its
/// key ring, and the per-key stream factory.
final class ChainEntry {
  /// Creates a chain entry.
  const ChainEntry({
    required this.model,
    required this.keyRing,
    required this.streamForKey,
  });

  /// The model this entry calls (carries provider/baseUrl/limits).
  final Model model;

  /// This entry's API-key stack (round-robin + backoff).
  final ApiKeyRing keyRing;

  /// Builds the provider [StreamFunction] bound to one API key value.
  final StreamFunction Function(String apiKey) streamForKey;

  /// The `provider/modelId` display label.
  String get label => '${model.provider}/${model.id}';
}

sealed class _AttemptOutcome {
  const _AttemptOutcome();
}

/// The attempt's events (or its terminal failure) were forwarded to the
/// caller; the wrapper's work is done.
final class _Forwarded extends _AttemptOutcome {
  const _Forwarded({this.succeeded = false, this.death, this.deathText});

  /// Issue #418 (UT-26): a post-commit (mid-answer) queue death — the
  /// turn stands, but the cursor advances for the NEXT call.
  final QueueDeath? death;

  /// The death's short error text (for the queue health story).
  final String? deathText;

  /// Whether a DoneEvent was forwarded — the entry served the request and
  /// its health counters reset (queue mode bookkeeping).
  final bool succeeded;
}

/// The attempt failed with a retryable error (rate-limit/quota or a
/// transient transport failure) before any observable output; nothing was
/// forwarded.
final class _Retryable extends _AttemptOutcome {
  const _Retryable(
    this.retryAfter,
    this.error, {
    this.isTransport = false,
    this.isRateLimit = false,
    this.deathKind,
    this.deathCooldown,
    this.immediate = false,
  });

  /// The provider's `Retry-After` hint, when sent.
  final Duration? retryAfter;

  /// The terminal error message (kept for the final forward if the chain
  /// exhausts).
  final AssistantMessage error;

  /// True for transient transport failures (dropped connection, DNS/TLS,
  /// 502/503/504): retried in place — key rotation is pointless when the
  /// endpoint, not the credential, failed.
  final bool isTransport;

  /// Whether the failure is the rate-limit/quota family — the class the
  /// waited-total accounting follows (issue #1066). Roles mode: the
  /// complement of [isTransport]. Queue mode: a quota death (there
  /// [isTransport] only means "skip key rotation", whatever the class).
  final bool isRateLimit;

  /// Issue #418: the queue death kind (null in roles mode).
  final QueueDeathKind? deathKind;

  /// Issue #418: the death's explicit base cooldown (quota default when
  /// the provider sent no `Retry-After`); null derives from [retryAfter]
  /// and the policy backoff.
  final Duration? deathCooldown;

  /// Issue #418: skip the retry ladder and advance to the next entry at
  /// once (auth — the key is dead).
  final bool immediate;
}

/// Mutable state of one [_drive] call, extracted so the event-loop phases
/// can live in small methods instead of closures over shared locals.
final class _DriveState {
  _DriveState(this.entryIndex, this.startedAt) : tried = {entryIndex};

  /// The chain entry currently being attempted.
  int entryIndex;

  /// Entries already tried in this call.
  final Set<int> tried;

  /// Paid retries spent on the current entry.
  var attemptsOnEntry = 0;

  /// Rate-limit failures seen in this call.
  var failures = 0;

  /// The most recent retryable failure (forwarded if the chain exhausts).
  _Retryable? lastFailure;

  /// The credential for the next attempt (null = re-select).
  ApiKeyCredential? credential;

  /// When the call started (the exhaustion story reports the elapsed time).
  final DateTime startedAt;

  /// Total time slept waiting out RATE-LIMIT waits in this call (the
  /// exhaustion story reports it, issue #1066). Keyed on the failure
  /// class ([_Retryable.isRateLimit]), not the rotation flag: transport
  /// outages don't count (the label must not call an outage a rate
  /// limit), queue-mode quota waits do.
  var rateLimitWaitTotal = Duration.zero;

  /// One bounded line per failed attempt (the exhaustion story's
  /// per-attempt outcomes, issue #290 AC2).
  final List<String> attemptLog = [];
}

/// Rewrites a post-commit retryable-class failure into the mid-answer
/// terminal error (AC4). Other failures keep their own story (auth,
/// overflow — those policies own them).
ErrorEvent _midAnswerEvent(ErrorEvent event) {
  final error = event.error;
  // Issue #312: a classified non-terminal finish_reason mid-answer gets
  // the same hygiene wrap (the transcript already holds the deltas); a
  // TERMINAL verdict (content_filter family) keeps its verbatim story.
  final retryClass = finishReasonRetryClass(error);
  final retryable =
      event.reason == StopReason.error &&
      (isRateLimitOrQuota(error, retryAfter: event.retryAfter) ||
          isTransientTransportError(error) ||
          (retryClass != null && retryClass != FinishReasonClass.terminal));
  if (!retryable) return event;
  return ErrorEvent(
    reason: event.reason,
    retryAfter: event.retryAfter,
    error: AssistantMessage(
      content: error.content,
      api: error.api,
      provider: error.provider,
      model: error.model,
      usage: error.usage,
      stopReason: error.stopReason,
      errorMessage:
          'Provider failed mid-answer: the stream died after output was '
          'already delivered (not retried — a replay would duplicate the '
          'transcript). Provider error: '
          '${FallbackStreamFunction._shortReasonText(error)}',
      rawStopReason: error.rawStopReason,
      timestamp: error.timestamp,
    ),
  );
}

/// Compact cooldown ETA for queue notices (`45s`, `12m`).
String _etaText(Duration remaining) => remaining.inMinutes >= 1
    ? '${remaining.inMinutes}m'
    : '${remaining.inSeconds}s';

/// Buffers one attempt's events until the first observable output commits
/// the attempt (omp's observable-output guard): a rate-limited attempt that
/// fails before any content leaves no trace in the caller's transcript.
final class _AttemptBuffer {
  _AttemptBuffer([this._queueClassifier]);

  /// Issue #418: the queue death classifier, or null in roles mode.
  final QueueDeathClassifier? _queueClassifier;

  final _buffer = <AssistantMessageEvent>[];
  var _committed = false;

  /// Feeds one event; returns the terminal outcome, or null to keep
  /// streaming.
  _AttemptOutcome? accept(
    AssistantMessageEventStream out,
    AssistantMessageEvent event,
  ) {
    if (_committed) {
      return _forwardCommitted(out, event);
    }
    switch (event) {
      case DoneEvent():
        _buffer.forEach(out.push);
        out.push(event);
        return const _Forwarded(succeeded: true);
      case ErrorEvent():
        return _forwardOrRetryable(out, event);
      case StartEvent():
        _buffer.add(event);
        return null;
      default:
        // Any content event commits the attempt (omp's observable-output
        // guard): from here events stream live and a later failure stands.
        _committed = true;
        _buffer.forEach(out.push);
        out.push(event);
        return null;
    }
  }

  /// Post-commit events stream live; a terminal event ends the attempt. A
  /// retryable-class failure here stands (issue #290 AC4 — observable
  /// output already left; a replay would duplicate the transcript), but it
  /// surfaces as a clean mid-answer error, never a naked provider dump.
  _AttemptOutcome? _forwardCommitted(
    AssistantMessageEventStream out,
    AssistantMessageEvent event,
  ) {
    if (event is ErrorEvent) {
      out.push(_midAnswerEvent(event));
      // The turn stands (no replay — issue #290), but the queue records
      // the death and advances the cursor for the next call (UT-26).
      return _Forwarded(
        death: _queueClassifier?.call(event),
        deathText: (event.error.errorMessage ?? '').split('\n').first,
      );
    }
    if (event is DoneEvent) {
      out.push(event);
      // A completed answer is a success for queue health even when content
      // already streamed (mid-answer completions heal the entry — AC5).
      return const _Forwarded(succeeded: true);
    }
    out.push(event);
    return null;
  }

  /// A pre-commit error: a retryable rate-limit or transport failure is
  /// held back (the buffer is discarded and the chain retries); anything
  /// else is forwarded verbatim.
  _AttemptOutcome _forwardOrRetryable(
    AssistantMessageEventStream out,
    ErrorEvent event,
  ) {
    // Issue #418: queue mode — the classifier is the single decision
    // point. A death rides the retry ladder (or advances at once for
    // auth); a null answer (content_filter family, user abort, unknown)
    // surfaces verbatim.
    final classifier = _queueClassifier;
    if (classifier != null) {
      final death = event.reason == StopReason.error ? classifier(event) : null;
      if (death == null) {
        _buffer.forEach(out.push);
        out.push(event);
        return const _Forwarded();
      }
      return _Retryable(
        event.retryAfter,
        event.error,
        isTransport: true,
        isRateLimit: death.kind == QueueDeathKind.quota,
        deathKind: death.kind,
        deathCooldown: death.cooldown,
        immediate: death.immediate,
      );
    }
    // Issue #926: budget/spending exhaustion is dead until the budget
    // reset — no paid retries, advance to the next chain entry at once
    // (the modelFallback notice carries the provider's budget wording).
    if (event.reason == StopReason.error && isBudgetExhaustion(event.error)) {
      return _Retryable(event.retryAfter, event.error, immediate: true);
    }
    if (event.reason == StopReason.error &&
        isRateLimitOrQuota(event.error, retryAfter: event.retryAfter)) {
      // Not forwarded: the buffer is discarded and the chain retries.
      return _Retryable(event.retryAfter, event.error, isRateLimit: true);
    }
    final retryClass = finishReasonRetryClass(event.error);
    if (event.reason == StopReason.error &&
        (retryClass != null
            ? retryClass != FinishReasonClass.terminal
            : isTransientTransportError(event.error))) {
      // Not forwarded: same retry path, but the in-place policy (no key
      // rotation) — see [_onRetryable]. A classified finish_reason
      // (issue #312) rides it too: terminal (content_filter family)
      // never retries, transient/unknown vendor words do.
      return _Retryable(event.retryAfter, event.error, isTransport: true);
    }
    _buffer.forEach(out.push);
    out.push(event);
    return const _Forwarded();
  }

  /// Flushes the buffered events (stream closed without a terminal event).
  void flushTo(AssistantMessageEventStream out) => _buffer.forEach(out.push);
}

/// A [StreamFunction] over an ordered [ChainEntry] list with omp's
/// rate-limit policy: rotate keys for free, retry the entry with capped
/// exponential backoff, then fail over to the next entry — or, when no
/// other entry is available, wait out a transient rate limit (bounded by
/// `maxWaitForLastEntry`, issue #1066) — every step announced through
/// [onNotice].
///
/// One instance is stateful and long-lived (a session): entry cooldowns and
/// the [activeIndex] persist across calls, and a later call starts at the
/// first entry not in cooldown (omp's `cooldown-expiry` revert policy — the
/// primary model is retried once its cooldown lapses).
final class FallbackStreamFunction {
  /// Creates the wrapper. [entries] must be non-empty. [jitterFraction] and
  /// [sleeper] are injectable for deterministic tests.
  FallbackStreamFunction({
    required List<ChainEntry> entries,
    this.policy = const ModelRolesRetryPolicy(),
    this.onNotice,
    DateTime Function()? now,
    double Function()? jitterFraction,
    Future<bool> Function(Duration delay, CancelToken? cancelToken)? sleeper,

    /// Issue #418: when set, the queue death classifier decides what
    /// advances (7 death kinds) and what surfaces verbatim
    /// (content_filter/user abort). Null keeps the classic rate-limit +
    /// transport policy byte-identical.
    this.queueClassifier,

    /// Issue #418: the sticky-cursor/health state the queue editor reads.
    /// Null in roles mode.
    this.queueState,

    /// Issue #823 (AC8): the quota depletion hint. A depleted provider is
    /// SOFT-BENCHED — selection prefers non-depleted entries, but a fully
    /// depleted chain still serves (order-based pick), never dead-ends a
    /// run. The feed is consulted fresh at every decision and a throwing
    /// feed counts as "not depleted". Null keeps routing byte-identical.
    this.quotaFeed,
  }) : _entries = List.unmodifiable(entries),
       _now = now ?? DateTime.now,
       _jitterFraction = jitterFraction ?? Random().nextDouble,
       _sleeper = sleeper ?? _defaultSleeper {
    if (entries.isEmpty) {
      throw ArgumentError.value(
        entries,
        'entries',
        'a fallback chain needs at least one entry',
      );
    }
  }

  /// The queue death classifier (issue #418); null in roles mode.
  final QueueDeathClassifier? queueClassifier;

  /// The queue's sticky cursor + per-entry health; null in roles mode.
  final ProviderQueueState? queueState;

  /// The quota depletion hint (issue #823 AC8); null keeps routing
  /// byte-identical.
  final QuotaFeed? quotaFeed;

  final List<ChainEntry> _entries;
  final DateTime Function() _now;
  final double Function() _jitterFraction;
  final Future<bool> Function(Duration delay, CancelToken? cancelToken)
  _sleeper;
  final _cooldownUntil = <int, DateTime>{};

  /// Retry/fallback knobs.
  final ModelRolesRetryPolicy policy;

  /// Receives a [FallbackNotice] before every retry/rotation/failover.
  final void Function(FallbackNotice notice)? onNotice;

  /// The chain entry the last call started on (display state for `/model`).
  int get activeIndex => _activeIndex;
  var _activeIndex = 0;

  /// The chain entry count.
  int get length => _entries.length;

  /// The model currently considered primary for this chain (first entry not
  /// in cooldown).
  Model get currentModel => _entries[_firstAvailableIndex()].model;

  /// Whether chain entry [index] is cooling down right now.
  bool isInCooldown(int index) {
    final until = _cooldownUntil[index];
    if (until == null) return false;
    if (_now().isBefore(until)) return true;
    _cooldownUntil.remove(index);
    return false;
  }

  /// Remaining cooldown of entry [index], or null when not cooling down.
  Duration? cooldownRemaining(int index) {
    if (!isInCooldown(index)) return null;
    return _cooldownUntil[index]!.difference(_now());
  }

  /// Whether entry [index]'s provider is depleted per the quota feed
  /// (issue #823). A steering hint only: a null feed and a throwing feed
  /// both degrade to "not depleted" — a broken feed must never break
  /// streaming. Consulted fresh at every decision, never cached.
  bool _isDepleted(int index) {
    final feed = quotaFeed;
    if (feed == null) return false;
    try {
      return feed.isDepleted(_entries[index].model.provider);
    } catch (_) {
      return false;
    }
  }

  /// The [StreamFunction] entry point. The passed [model] is ignored — the
  /// chain position decides which model is called (the loop passes its
  /// configured model; the resolver keeps `AgentState.model` in sync).
  AssistantMessageEventStream call(
    Model model,
    Context context, {
    CancelToken? cancelToken,
  }) {
    final out = AssistantMessageEventStream();
    unawaited(
      _drive(out, context, cancelToken)
          .catchError((Object error) {
            // Defensive (providers never throw; a fake in tests might):
            // convert into the errors-as-events contract.
            final failure = _terminalMessage(
              _entries[_activeIndex].model,
              StopReason.error,
              '$error',
            );
            out.push(ErrorEvent(reason: StopReason.error, error: failure));
          })
          .whenComplete(out.end),
    );
    return out;
  }

  Future<void> _drive(
    AssistantMessageEventStream out,
    Context context,
    CancelToken? cancelToken,
  ) async {
    final state = _DriveState(_firstAvailableIndex(), _now());
    _activeIndex = state.entryIndex;
    queueState?.recordCurrentIndex(state.entryIndex);
    // Issue #418 (UT-23): every entry cooling — die loud with per-entry
    // ETAs instead of silently hammering a benched head.
    final queue = queueState;
    if (queue != null) {
      final now = _now();
      final etas = <String>[
        for (var index = 0; index < _entries.length; index++)
          if (queue.cooldownRemaining(index, now) case final left?)
            '${_entries[index].label} ready in ${_etaText(left)}',
      ];
      if (etas.length == _entries.length) {
        out.push(
          ErrorEvent(
            reason: StopReason.error,
            error: _terminalMessage(
              _entries.first.model,
              StopReason.error,
              'Provider queue cooling down: every entry is in cooldown — '
              '${etas.join(', ')}.',
            ),
          ),
        );
        return;
      }
    }
    while (true) {
      if (cancelToken?.isCancelled ?? false) {
        _pushAborted(out, _entries[state.entryIndex].model);
        return;
      }
      final entry = _entries[state.entryIndex];

      // Credential selection: affinity key unless benched (omp's
      // skip-blocked-sibling rule).
      state.credential ??= entry.keyRing.availableCredential;
      final credential = state.credential;
      if (credential == null) {
        if (!await _onNoCredential(out, state, entry, cancelToken)) return;
        continue;
      }

      if (!await _runAndDispatch(
        out,
        state,
        entry,
        credential,
        context,
        cancelToken,
      )) {
        return;
      }
    }
  }

  /// Runs one attempt on [entry] and dispatches its outcome: forwarded
  /// events end the run (returns false); a retryable rate-limit runs omp's
  /// rotate/retry/fail-over policy and reports whether the loop continues.
  Future<bool> _runAndDispatch(
    AssistantMessageEventStream out,
    _DriveState state,
    ChainEntry entry,
    ApiKeyCredential credential,
    Context context,
    CancelToken? cancelToken,
  ) async {
    final outcome = await _runAttempt(
      out,
      entry,
      credential,
      context,
      cancelToken,
    );
    switch (outcome) {
      case _Forwarded(:final succeeded, :final death):
        if (succeeded) queueState?.recordSuccess(state.entryIndex);
        if (death != null) {
          _markMidAnswerDeath(state, death, outcome.deathText);
        }
        return false;
      case _Retryable():
        return _onRetryable(
          out,
          state,
          entry,
          credential,
          outcome,
          cancelToken,
        );
    }
  }

  /// Selects the next entry after the current one gave up. Returns false
  /// when the chain is exhausted (the last failure has been forwarded).
  bool _failOver(
    AssistantMessageEventStream out,
    _DriveState state, {
    bool noCooldown = false,
  }) {
    final next = _failover(
      state.entryIndex,
      state.tried,
      state.lastFailure,
      failures: state.failures,
      noCooldown: noCooldown,
    );
    if (next == null) {
      _forwardLastFailure(out, state);
      return false;
    }
    state.entryIndex = next;
    _activeIndex = next;
    state.tried.add(next);
    state.attemptsOnEntry = 0;
    // A fresh entry always gets one attempt with its ring's best
    // credential: backoff guides key *selection*, but a benched shared
    // credential must not block the take-over (different model, often a
    // different quota bucket).
    final ring = _entries[next].keyRing;
    state.credential = ring.availableCredential ?? ring.currentCredential;
    return true;
  }

  /// Issue #418 (UT-26): a mid-answer death stands (the turn is already
  /// on the wire), but the queue health records it and the sticky cursor
  /// advances so the NEXT call starts on the next entry.
  void _markMidAnswerDeath(
    _DriveState state,
    QueueDeath death,
    String? errorText,
  ) {
    final qState = queueState;
    if (qState == null) return;
    final from = state.entryIndex;
    final count = qState.recordFailure(from, death.kind, errorText ?? '');
    if (!death.immediate) {
      final base = death.cooldown ?? policy.keyBackoff;
      final doubled = base * (1 << (count - 1).clamp(0, 7));
      final cap = const Duration(hours: 24);
      final until = _now().add(doubled > cap ? cap : doubled);
      _cooldownUntil[from] = until;
      qState.recordCooldown(from, until);
    }
    final next = (from + 1) % _entries.length;
    qState.recordCurrentIndex(next);
    _activeIndex = next;
  }

  /// Paid same-entry retry: sleeps once, then forces the next iteration to
  /// run an attempt. Returns false on abort or when control moved on.
  /// [isTransport] selects the notice kind (the rotation-policy flag);
  /// [isRateLimitWait] is the failure class the waited-total accounting
  /// follows (issue #1066, review round 2: never infer one from the
  /// other — queue mode runs transport-flagged quota deaths).
  Future<bool> _sleepAndRetry(
    AssistantMessageEventStream out,
    _DriveState state,
    Duration delay,
    String reason,
    CancelToken? cancelToken, {
    bool isTransport = false,
    bool isRateLimitWait = false,
  }) async {
    state.attemptsOnEntry++;
    state.failures++;
    _notify(
      FallbackNotice(
        kind: isTransport
            ? FallbackNoticeKind.transportRetry
            : FallbackNoticeKind.retry,
        fromModel: _entries[state.entryIndex].label,
        delay: delay,
        attempt: state.failures,
        reason: reason,
      ),
    );
    if (!await _sleeper(delay, cancelToken)) {
      _pushAborted(out, _entries[state.entryIndex].model);
      return false;
    }
    if (isRateLimitWait) state.rateLimitWaitTotal += delay;
    // After the wait: a single-key ring reuses its (benched) key — omp
    // retries the current credential after local backoff; our own bench
    // must not deadlock the retry. Multi-key rings re-select, picking up
    // any sibling whose backoff lapsed during the sleep.
    state.credential = _entries[state.entryIndex].keyRing.length == 1
        ? _entries[state.entryIndex].keyRing.currentCredential
        : null;
    return true;
  }

  /// Every key of [entry] is benched right now: wait for the earliest to
  /// free up, or fail over when the retries are spent / the wait exceeds
  /// the cap. Returns false when the run ends (exhausted or aborted).
  Future<bool> _onNoCredential(
    AssistantMessageEventStream out,
    _DriveState state,
    ChainEntry entry,
    CancelToken? cancelToken,
  ) async {
    if (state.attemptsOnEntry >= policy.retriesPerEntry) {
      return _failOver(out, state);
    }
    final Duration wait;
    if (entry.keyRing.length > 1) {
      // omp's sibling-credential wait: pause until the earliest benched
      // key frees up (plus its 1s buffer).
      wait =
          entry.keyRing.earliestBackoffEnd!.difference(_now()) +
          const Duration(seconds: 1);
    } else {
      wait = _retryDelay(
        state.attemptsOnEntry + 1,
        state.lastFailure?.retryAfter,
      );
    }
    final lastFailure = state.lastFailure;
    final reason = lastFailure == null
        ? 'all API keys in backoff'
        : _shortReasonText(lastFailure.error);
    if (wait > policy.maxWait) {
      return _onExcessiveWait(
        out,
        state,
        wait,
        reason,
        cancelToken,
        isRateLimit: true,
      );
    }
    return _sleepAndRetry(
      out,
      state,
      wait,
      reason,
      cancelToken,
      isRateLimitWait: true,
    );
  }

  /// The first entry outside [tried] that is not cooling down, or null —
  /// the single source of truth for failover target selection, shared
  /// with the sole-entry wait-out check (issue #1066). Issue #823 (AC8):
  /// depleted entries are soft-benched — the scan prefers non-depleted
  /// candidates; when every candidate is depleted the first order pick
  /// still wins (a depleted provider serves rather than dead-ends the
  /// run).
  int? _failoverTarget(Set<int> tried) {
    int? depleted;
    for (var index = 0; index < _entries.length; index++) {
      if (tried.contains(index) || isInCooldown(index)) continue;
      if (!_isDepleted(index)) return index;
      depleted ??= index;
    }
    return depleted;
  }

  /// Issue #1066: the required retry wait exceeds the failover threshold
  /// ([ModelRolesRetryPolicy.maxWait]). With a fallback entry available
  /// this fails over immediately (unchanged); on the sole/last eligible
  /// entry failover is impossible, so the chain waits out the rate limit
  /// instead of dying in <1s — bounded by
  /// [ModelRolesRetryPolicy.maxWaitForLastEntry] so a pathological
  /// `Retry-After` (hours) still ends the chain. The wait-out consumes
  /// attempts like any paid retry ([_sleepAndRetry]); [isRateLimit] (the
  /// failure class) keys the waited-total accounting and, for queue-mode
  /// quota wait-outs, corrects the notice kind that the rotation flag
  /// alone would mislabel as a transport retry.
  Future<bool> _onExcessiveWait(
    AssistantMessageEventStream out,
    _DriveState state,
    Duration delay,
    String reason,
    CancelToken? cancelToken, {
    bool isTransport = false,
    bool isRateLimit = false,
  }) async {
    if (_failoverTarget(state.tried) != null) {
      return _failOver(out, state);
    }
    final bounded =
        delay < policy.maxWaitForLastEntry ? delay : policy.maxWaitForLastEntry;
    return _sleepAndRetry(
      out,
      state,
      bounded,
      reason,
      cancelToken,
      isTransport: isTransport && !isRateLimit,
      isRateLimitWait: isRateLimit,
    );
  }

  /// Handles a retryable failure. Rate-limits follow omp's order: free
  /// credential switch first, then paid retries, then model fallback.
  /// Transport failures skip the credential layer entirely (the endpoint
  /// dropped, not the key) and go straight to paid in-place retries, then
  /// fall over. Returns false when the run ends (exhausted or aborted).
  Future<bool> _onRetryable(
    AssistantMessageEventStream out,
    _DriveState state,
    ChainEntry entry,
    ApiKeyCredential attemptCredential,
    _Retryable outcome,
    CancelToken? cancelToken,
  ) async {
    state.lastFailure = outcome;
    state.attemptLog.add('${entry.label}: ${_shortReasonText(outcome.error)}');
    // Issue #418 (UT-10): auth is a dead key — no retries, no cooldown,
    // advance to the next entry at once.
    if (outcome.immediate) {
      return _failOver(out, state, noCooldown: true);
    }
    if (!outcome.isTransport) {
      entry.keyRing.reportRateLimited(
        attemptCredential.name,
        outcome.retryAfter ?? policy.keyBackoff,
      );
      final rotated = entry.keyRing.rotate(attemptCredential.name);
      if (rotated != null) {
        entry.keyRing.stickTo(rotated);
        state.failures++;
        _notify(
          FallbackNotice(
            kind: FallbackNoticeKind.keyRotation,
            fromModel: entry.label,
            apiKeyName: rotated.name,
            delay: Duration.zero,
            attempt: state.failures,
            reason: _shortReasonText(outcome.error),
          ),
        );
        state.credential = rotated;
        return true;
      }
    }
    if (state.attemptsOnEntry >= policy.retriesPerEntry) {
      return _failOver(out, state);
    }
    final delay = _retryDelay(state.attemptsOnEntry + 1, outcome.retryAfter);
    if (delay > policy.maxWait) {
      return _onExcessiveWait(
        out,
        state,
        delay,
        _shortReasonText(outcome.error),
        cancelToken,
        isTransport: outcome.isTransport,
        isRateLimit: outcome.isRateLimit,
      );
    }
    return _sleepAndRetry(
      out,
      state,
      delay,
      _shortReasonText(outcome.error),
      cancelToken,
      isTransport: outcome.isTransport,
      isRateLimitWait: outcome.isRateLimit,
    );
  }

  /// Picks the next chain entry after [from], skipping entries already tried
  /// in this call and entries in cooldown; marks [from]'s cooldown. Returns
  /// `null` when the chain is exhausted.
  ///
  /// Issue #418: in queue mode the failure is recorded into the sticky
  /// state (kind + count), the cooldown doubles with each consecutive
  /// failure (capped at 24h), and the switch reason carries the exact
  /// death-kind label (UT-17). [noCooldown] (auth deaths) advances
  /// without benching the dead entry.
  int? _failover(
    int from,
    Set<int> tried,
    _Retryable? lastFailure, {
    required int failures,
    bool noCooldown = false,
  }) {
    final failure = lastFailure;
    final queueState = this.queueState;
    Duration cooldown;
    String reason;
    if (failure == null) {
      cooldown = policy.keyBackoff;
      reason = 'rate limited';
    } else if (queueState != null) {
      final count = queueState.recordFailure(
        from,
        failure.deathKind ?? QueueDeathKind.network,
        _shortReasonText(failure.error),
      );
      final base =
          failure.deathCooldown ?? failure.retryAfter ?? policy.keyBackoff;
      final doubled = base * (1 << (count - 1).clamp(0, 7));
      final cap = const Duration(hours: 24);
      final clamped = doubled > cap;
      cooldown = clamped ? cap : doubled;
      reason =
          '${failure.deathKind?.label ?? 'error'}: '
          '${_shortReasonText(failure.error)}'
          '${clamped ? ' (cooldown clamped to 24h)' : ''}';
    } else {
      cooldown = failure.retryAfter ?? policy.keyBackoff;
      reason = _shortReasonText(failure.error);
    }
    if (!noCooldown) {
      final until = _now().add(cooldown);
      _cooldownUntil[from] = until;
      queueState?.recordCooldown(from, until);
    }
    final next = _failoverTarget(tried);
    if (next == null) return null;
    onNotice?.call(
      FallbackNotice(
        kind: FallbackNoticeKind.modelFallback,
        fromModel: _entries[from].label,
        toModel: _entries[next].label,
        delay: Duration.zero,
        attempt: failures,
        reason: reason,
      ),
    );
    return next;
  }

  /// Per-entry health for the exhausted-chain terminal (UT-24): every
  /// entry with its last death kind, error line, and failure count.
  String _queueHealthSummary() {
    final state = queueState!;
    return [
      for (var index = 0; index < _entries.length; index++)
        '${_entries[index].label}: '
            '${state.lastErrorKind(index)?.label ?? 'unknown'}'
            '${state.consecutiveFailures(index) > 0 ? ' x${state.consecutiveFailures(index)}' : ''}'
            '${state.lastError(index) == null ? '' : ' — ${state.lastError(index)}'}',
    ].join('; ');
  }

  Duration _retryDelay(int attempt, Duration? retryAfter) {
    if (retryAfter != null) return retryAfter;
    return policy.backoffFor(attempt, _jitterFraction());
  }

  /// First entry not in cooldown (omp's cooldown-expiry revert policy);
  /// falls back to entry 0 when every entry is cooling down. Issue #823
  /// (AC8): depleted entries are soft-benched — the scan prefers
  /// non-depleted entries; when every entry is depleted the first order
  /// pick still serves.
  int _firstAvailableIndex() {
    int? depleted;
    for (var index = 0; index < _entries.length; index++) {
      if (isInCooldown(index)) continue;
      if (!_isDepleted(index)) return index;
      depleted ??= index;
    }
    return depleted ?? 0;
  }

  /// Streams one attempt, buffering events until the first observable output
  /// so a rate-limited attempt leaves no trace in the caller's transcript.
  Future<_AttemptOutcome> _runAttempt(
    AssistantMessageEventStream out,
    ChainEntry entry,
    ApiKeyCredential credential,
    Context context,
    CancelToken? cancelToken,
  ) async {
    final stream = entry.streamForKey(credential.value)(
      entry.model,
      context,
      cancelToken: cancelToken,
    );
    final attempt = _AttemptBuffer(queueClassifier);

    await for (final event in stream) {
      final outcome = attempt.accept(out, event);
      if (outcome != null) return outcome;
    }
    // Provider bug (stream closed without a terminal event): flush what we
    // have; the agent loop synthesizes the terminal error.
    attempt.flushTo(out);
    return const _Forwarded();
  }

  /// Chain exhausted (issue #290 AC2/E1): the terminal error carries the
  /// retry story — attempts, elapsed, per-attempt outcomes, the
  /// whole-chain-failed wording, a next-step hint — with the raw provider
  /// lines only as evidence inside, never as the headline.
  void _forwardLastFailure(AssistantMessageEventStream out, _DriveState state) {
    final entry = _entries[state.entryIndex];
    final failure = state.lastFailure;
    if (failure == null) {
      out.push(
        ErrorEvent(
          reason: StopReason.error,
          error: _terminalMessage(
            entry.model,
            StopReason.error,
            'Provider chain exhausted: every chain model is rate limited and '
            'cooling down. The primary model is retried automatically '
            'once its cooldown lapses — check the provider status or try '
            'again later.',
          ),
        ),
      );
      return;
    }
    final elapsed = _now().difference(state.startedAt);
    final elapsedText = elapsed.inSeconds < 1 ? '<1s' : '${elapsed.inSeconds}s';
    // Issue #1066: say how long the chain already waited out rate limits
    // before giving up.
    final waited = state.rateLimitWaitTotal;
    final waitedText = waited.inSeconds < 1
        ? ''
        : ' (waited ${_etaText(waited)} on rate limits)';
    final log = state.attemptLog
        .map(
          (line) =>
              line.endsWith('.') ? line.substring(0, line.length - 1) : line,
        )
        .join('; ');
    final queueLines = queueState == null
        ? ''
        : ' Queue health: ${_queueHealthSummary()}.';
    final story =
        'Provider chain exhausted: ${state.tried.length} of '
        '${_entries.length} chain model(s) failed after '
        '${state.attemptLog.length} attempt(s) over $elapsedText$waitedText. '
        'Attempts: $log.$queueLines '
        'All available models failed with provider-side errors — likely an '
        'outage or quota exhaustion, not a key problem. '
        'Check the provider status or try again later.';
    out.push(
      ErrorEvent(
        reason: StopReason.error,
        error: _terminalMessage(entry.model, StopReason.error, story),
      ),
    );
  }

  void _pushAborted(AssistantMessageEventStream out, Model model) {
    final message = _terminalMessage(
      model,
      StopReason.aborted,
      'Request was aborted',
    );
    out.push(ErrorEvent(reason: StopReason.aborted, error: message));
  }

  AssistantMessage _terminalMessage(
    Model model,
    StopReason reason,
    String text,
  ) {
    return AssistantMessage(
      content: const [],
      api: model.api,
      provider: model.provider,
      model: model.id,
      usage: Usage.zero,
      stopReason: reason,
      errorMessage: text,
      timestamp: _now(),
    );
  }

  void _notify(FallbackNotice notice) => onNotice?.call(notice);

  static String _shortReasonText(AssistantMessage error) {
    final text = (error.errorMessage ?? 'rate limited').split('\n').first;
    return text.length <= 120 ? text : '${text.substring(0, 120)}...';
  }

  /// Default sleeper: waits [delay], resolving `false` early when
  /// [cancelToken] fires.
  static Future<bool> _defaultSleeper(
    Duration delay,
    CancelToken? cancelToken,
  ) async {
    if (cancelToken == null) {
      await Future<void>.delayed(delay);
      return true;
    }
    final cancelled = await Future.any([
      Future<void>.delayed(delay).then((_) => false),
      cancelToken.onCancel.then((_) => true),
    ]);
    return !cancelled;
  }
}

/// The provider-queue runtime (issue #418): turns resolved
/// [ProviderQueueEntry] values into a [FallbackStreamFunction] chain with
/// the queue advance policy — seven death kinds (quota, auth, network,
/// timeout, malformed, 5xx, finish_reason), never advancing on
/// content_filter/user abort — plus the sticky RAM state the editor reads.
///
/// The queue REPLACES the main-model resolution: the default role resolves
/// through the queue head. The state object is volatile by contract — a
/// restart builds a fresh wrapper and the queue restarts at its head (AC6).
library;

import '../agent/agent_loop.dart';
import '../cancel_token.dart';
import '../providers/quota.dart';
import 'roles_config.dart';
import '../types.dart';
import '../exceptions.dart';
import 'fallback_stream.dart';
import 'key_rotation.dart';
import 'provider_catalog.dart';
import 'providers_queue.dart';

/// Cooldown applied to a quota death when the provider sent no
/// `Retry-After` (issue #418 open question 1 — proposed 60s; flip to 30s
/// here for snappier rotation).
const defaultProviderQueueCooldown = Duration(seconds: 60);

/// Classifies an error event into a queue death (issue #418 AC3/UT-13
/// kind strings). Returns `null` when the chain must NOT advance — the
/// content_filter finish_reason family, a user abort, and unknown errors
/// all surface verbatim (the roles precedent).
///
/// Precedence: budget → quota → auth → finish_reason → 5xx → malformed →
/// timeout → network.
QueueDeath? classifyQueueDeath(ErrorEvent event) {
  if (event.reason != StopReason.error) return null; // abort — never advance
  final text = event.error.errorMessage;
  if (text == null || text.isEmpty) return null;

  // Budget/spending exhaustion (issue #926): the entry is dead until the
  // budget reset — advance at once, no ladder, and the provider's budget
  // wording rides the switch event. Checked BEFORE the terminal
  // finish_reason veto (a budget death is not a content stop).
  //
  // Policy note (review #929): `immediate` deliberately benches the entry
  // with NO cooldown — reset-date-aware benching needs the structured
  // surface tracked in #898 — so the queue pays at most ONE cheap probe
  // per call against the dead head before failing over. Never sleeps,
  // never a ladder: the #926 flooding is gone, and the queue editor's
  // `recovering`/`healthy` badge must not be read as "will succeed"
  // while the budget stays exhausted.
  if (isBudgetExhaustion(event.error)) {
    return const QueueDeath(kind: QueueDeathKind.quota, immediate: true);
  }

  // Content_filter family (terminal finish_reason class, issue #312):
  // never a queue death — the error surfaces verbatim.
  final retryClass = finishReasonRetryClass(event.error);
  if (retryClass == FinishReasonClass.terminal) return null;

  // Quota: the rate-limit patterns own 429/quota wordings; the cooldown
  // follows the structured Retry-After, else the default.
  if (isRateLimitOrQuota(event.error, retryAfter: event.retryAfter)) {
    return QueueDeath(
      kind: QueueDeathKind.quota,
      cooldown: event.retryAfter ?? defaultProviderQueueCooldown,
    );
  }

  // Transient/unknown wire finish_reason after retries (issue #312).
  if (retryClass != null) {
    return const QueueDeath(kind: QueueDeathKind.finishReason);
  }

  // The labeled regex nets in precedence order, then the transport net;
  // null — unknown, forward verbatim, never advance on a guess.
  return _labeledDeath(text, event.error);
}

/// The labeled death kinds after quota/finish_reason (issue #418): auth,
/// 5xx, malformed, timeout, network. Null when none match — the caller
/// forwards verbatim.
QueueDeath? _labeledDeath(String text, AssistantMessage error) {
  // Auth: the key is dead — advance immediately, no cooldown (UT-10).
  if (_authPatterns.any((pattern) => pattern.hasMatch(text))) {
    return const QueueDeath(kind: QueueDeathKind.auth, immediate: true);
  }

  // 5xx family (gateways included) after the retry ladder is spent.
  if (_fivexxPatterns.any((pattern) => pattern.hasMatch(text))) {
    return const QueueDeath(kind: QueueDeathKind.fivexx);
  }

  // Malformed stream: bad SSE/non-JSON deltas, truncation without a
  // finish_reason (the 200-empty silent provider included).
  if (_malformedPatterns.any((pattern) => pattern.hasMatch(text))) {
    return const QueueDeath(kind: QueueDeathKind.malformed);
  }

  // Provider watchdog deaths (connect/stream-idle timeouts).
  if (_timeoutPatterns.any((pattern) => pattern.hasMatch(text))) {
    return const QueueDeath(kind: QueueDeathKind.timeout);
  }

  // Everything else the roles layer already calls transient transport:
  // dropped/refused/reset connections, DNS/TLS failures.
  if (isTransientTransportError(error)) {
    return const QueueDeath(kind: QueueDeathKind.network);
  }

  return null;
}

final _authPatterns = [
  RegExp(r'\b401\b'),
  RegExp(r'\b403\b'),
  RegExp(r'unauthorized', caseSensitive: false),
  RegExp(r'forbidden', caseSensitive: false),
  RegExp(r'invalid api key', caseSensitive: false),
  RegExp(r'invalid_api_key', caseSensitive: false),
  RegExp(r'incorrect api key', caseSensitive: false),
  RegExp(r'authentication', caseSensitive: false),
];

final _fivexxPatterns = [
  RegExp(r'\b50[0234]\b'),
  RegExp(r'bad gateway', caseSensitive: false),
  RegExp(r'service unavailable', caseSensitive: false),
  RegExp(r'gateway time-?out', caseSensitive: false),
  RegExp(r'internal (server|network) error', caseSensitive: false),
  RegExp(r'internal network failure', caseSensitive: false),
];

final _malformedPatterns = [
  RegExp(r'stream ended without finish_reason'),
  RegExp(r'format ?exception', caseSensitive: false),
  RegExp(r'invalid json', caseSensitive: false),
  RegExp(r'unexpected character', caseSensitive: false),
  RegExp(r'invalid sse', caseSensitive: false),
  RegExp(r'malformed', caseSensitive: false),
  RegExp(r'empty (stream|response)', caseSensitive: false),
];

final _timeoutPatterns = [
  RegExp(r'timeout ?exception', caseSensitive: false),
  RegExp(r'stream idle timeout', caseSensitive: false),
  RegExp(r'request (attempt )?timed? ?out', caseSensitive: false),
];

/// Maps a queue adapter kind to the catalog provider NAME the model
/// builder keys off — derived from the catalog ([resolveCliProviderSpec],
/// issue #772 AC3), never a hand-maintained map: a catalog addition flows
/// through with no edit here. `openai-completions` keeps the historical
/// CLI rule: a custom baseUrl reports provider `openai`, the default
/// reports `openrouter`.
String queueKindCatalogName(String kind, String? baseUrl) {
  final spec = resolveCliProviderSpec(kind, baseUrl: baseUrl);
  if (spec == null) {
    throw ConfigException(
      'unknown provider kind "$kind" — supported: '
      '${providerQueueKinds.join(', ')}',
    );
  }
  return spec.name;
}

/// Builds the [ChainEntry] list for a resolved queue: one model per entry
/// (catalog defaults + the entry's overrides), a single key stack per
/// entry from its `apiKeyEnv` (the `_2`/`_3` stack convention rides along
/// free), and the catalog stream factory bound per key.
///
/// Entries with no configured key are SKIPPED (the roles precedent) and
/// reported in [skipped]; a queue that skips everything throws
/// [ConfigException].
List<ChainEntry> buildProviderQueueChain(
  List<ProviderQueueEntry> entries, {
  required Map<String, String> secrets,
  StreamFunction Function(String kind, String apiKey)? streamFactory,
  List<String>? skipped,
}) {
  final skipped_ = skipped ?? <String>[];
  final factory = streamFactory ?? providerStreamFunction;
  final chain = <ChainEntry>[];
  for (final entry in entries) {
    final keyEnv = entry.apiKeyEnv;
    if (keyEnv == null) {
      throw ConfigException(
        'queue entry ${entry.label} has no apiKeyEnv — keys never ride in '
        'the queue blob; name the env var holding the key',
      );
    }
    final stack = collectKeyStack(secrets, keyEnv);
    if (stack.isEmpty) {
      skipped_.add('${entry.label} (missing API key: set $keyEnv)');
      continue;
    }
    final ring = ApiKeyRing(baseName: keyEnv, credentials: stack);
    final spec = catalogProvider(
      queueKindCatalogName(entry.providerType, entry.baseUrl),
    )!;
    final inner = factory(spec.kind, stack.first.value);
    chain.add(
      ChainEntry(
        model: buildCatalogModel(
          spec.name,
          entry.model,
          baseUrl: entry.baseUrl,
          contextWindow: entry.contextWindow,
          maxTokens: entry.maxTokens,
        ),
        keyRing: ring,
        streamForKey: (apiKey) =>
            inner, // single entry-bound adapter; the key is baked in
      ),
    );
  }
  if (chain.isEmpty) {
    throw ConfigException(
      'the provider queue has no usable entry: ${skipped_.join('; ')}',
    );
  }
  return chain;
}

/// The wired queue: the sticky RAM state, the driven stream function, and
/// the entries it was built from. Hosts keep ONE instance per session
/// (the stickiness); editors mutate the yaml and re-resolve — the next
/// `rebuild()` swaps the chain live (AC7/UT-31).
final class ProviderQueueRuntime {
  ProviderQueueRuntime._(
    this.resolution,
    this.entries,
    this.state,
    this.streamFunction,
  );

  /// Builds the runtime from a resolution and the secrets snapshot.
  /// [policy]/[now]/[jitterFraction]/[sleeper] pass through to the wrapper
  /// (tests inject a deterministic clock). [quotaFeed] threads through to
  /// the [FallbackStreamFunction] (issue #823 AC8 soft-bench); null keeps
  /// routing byte-identical.
  factory ProviderQueueRuntime.build(
    ProviderQueueResolution resolution, {
    required Map<String, String> secrets,
    StreamFunction Function(String kind, String apiKey)? streamFactory,
    ModelRolesRetryPolicy policy = const ModelRolesRetryPolicy(),
    DateTime Function()? now,
    double Function()? jitterFraction,
    Future<bool> Function(Duration delay, CancelToken? cancelToken)? sleeper,
    void Function(FallbackNotice notice)? onNotice,
    QuotaFeed? quotaFeed,
  }) {
    final entries = resolution.entries;
    final state = ProviderQueueState();
    final chain = buildProviderQueueChain(
      entries,
      secrets: secrets,
      streamFactory: streamFactory,
    );
    final streamFunction = FallbackStreamFunction(
      entries: chain,
      policy: policy,
      queueClassifier: classifyQueueDeath,
      queueState: state,
      now: now,
      jitterFraction: jitterFraction,
      sleeper: sleeper,
      onNotice: onNotice,
      quotaFeed: quotaFeed,
    );
    return ProviderQueueRuntime._(resolution, entries, state, streamFunction);
  }

  /// The winning scope, entries, shadowed scopes, and boot notices.
  final ProviderQueueResolution resolution;

  /// The resolved (refs materialized) queue entries.
  final List<ProviderQueueEntry> entries;

  /// The sticky cursor + per-entry health (never persisted).
  final ProviderQueueState state;

  /// The queue-driven stream function — the default role's stream.
  final FallbackStreamFunction streamFunction;
}

/// The queue editor's per-entry health rows — pure so tests pin the byte
/// layout across the four health states (current / healthy / recovering /
/// cooldown) and any terminal width (issue #418, GOLDEN-tui-rows).
///
/// Secrets never appear: the row names the key's ENV indirection
/// (`key:$NAME`), never a value (AC9).
List<String> renderProviderQueueRows({
  required List<ProviderQueueEntry> entries,
  required ProviderQueueState state,
  required DateTime now,
}) {
  final rows = <String>[];
  for (var index = 0; index < entries.length; index++) {
    final entry = entries[index];
    final badge = index == state.currentIndex
        ? 'current'
        : switch (state.cooldownRemaining(index, now)) {
            null => state.lastError(index) == null ? 'healthy' : 'recovering',
            final left =>
              'cooldown ${left.inMinutes >= 1 ? '${left.inMinutes}m' : '${left.inSeconds}s'}',
          };
    final error = state.lastError(index);
    rows.add(
      '$index. ${entry.label} [$badge]'
      '${entry.apiKeyEnv == null ? '' : ' key:\$${entry.apiKeyEnv}'}'
      '${entry.baseUrl == null ? '' : ' ${entry.baseUrl}'}'
      '${error == null ? '' : ' — ${state.lastErrorKind(index)?.label}: $error'}',
    );
  }
  return rows;
}

/// The REPL entries of [AgentCli]: the line-mode read-dispatch loop and
/// the TUI boot (with `_setTuiIo`/`_createTuiController`). Their public
/// helpers — `sessionResumeHint`, `waitForIdle`, `deleteSessionIfEmpty` —
/// stay class members of `agent_cli.dart`: callers outside this library
/// (the executable's SIGINT path, tests) cannot see a private extension.
/// Split out of `agent_cli.dart` to keep that file under the repo's
/// 2800-line size gate. Same library (a `part of`), so the extension sees
/// the class's private members.
part of 'agent_cli.dart';

/// Implementation members of [AgentCli] for the REPL entries.
extension on AgentCli {
  /// The line-mode REPL: banner, restored-session replay, then the
  /// read-dispatch loop.
  Future<void> _runLineRepl() async {
    final lineIterator = await _primeLineModeInput();
    while (await lineIterator.moveNext()) {
      var line = lineIterator.current;
      // A fresh user line clears the abort marker: the settle path already
      // dropped (or ran) the interrupted run's leftover steering.
      _abortRequested = false;
      if (line.trim() == '/') {
        final choice = await _showLineModeMenu(lineIterator);
        if (choice != null) line = choice;
      }
      await _handleLine(line);
      if (_exited) break;
      // No idle prompt while a guided flow owns input: its questions
      // would interleave with the status bar, and each answered prompt
      // would print a redundant one.
      if (!isBusy && !_providerFlowActive) _writeIdlePrompt();
    }
  }

  /// Everything that must happen before the line-mode dispatch loop reads
  /// its first line: the banner, the restored-session replay, the one-time
  /// skills-consent question, and the fresh-install wizard (issue #969)
  /// with its idle-prompt restoration. Returns the iterator the loop reads
  /// from — the prologue reads answers straight from the line stream
  /// (the dispatch loop is not running yet, so this pre-loop iterator
  /// cannot route to `_pendingPromptAnswer`).
  Future<StreamIterator<String>> _primeLineModeInput() async {
    await _printBanner();
    await _printViewerBannerIfAny();
    // Warm the model cache here too (the TUI path does): the endpoint-
    // reported context window lands on the active model only through this
    // refresh, and line-mode `/model <id>` switches read the same map.
    unawaited(_refreshModelCache());
    final resumedLabel = await _resumedSessionLabel();
    if (resumedLabel != null) {
      _replayRestoredHistory(_agent.state.messages, resumedLabel);
    }
    // One-time consent question for third-party skill roots: reads answers
    // straight from the line stream (the dispatch loop is not running yet).
    final lineIterator = StreamIterator<String>(io.lines);
    await _maybePromptSkillsAccess(lineIterator: lineIterator);
    // Fresh install (issue #969): nothing configured, no key anywhere —
    // open the guided add-provider wizard before the first prompt. The
    // dispatch loop below answers its prompts (the pre-loop lineIterator
    // cannot route to `_pendingPromptAnswer`). The wizard completes
    // OUTSIDE `_handleLine`: once its last answer lands, the loop is
    // already parked in `moveNext` — so the idle prompt is restored from
    // the flow's own completion (also after a Ctrl-C cancel).
    final freshInstallFlow = _maybeStartFreshInstallProviderFlow();
    if (freshInstallFlow != null) {
      unawaited(
        freshInstallFlow.whenComplete(() {
          if (!_exited && !isBusy && !_providerFlowActive) {
            _writeIdlePrompt();
          }
        }),
      );
    }
    if (!_providerFlowActive) _writeIdlePrompt();
    return lineIterator;
  }

  Future<void> _runTuiRepl() async {
    // Busy-row forensics: every arm/release/drop/watchdog-fire lands in
    // fa.log with its source — a wedged "Working…" names its owner.
    faTuiBusyDiagnostics = _logDiagnostic;
    final controller = _createTuiController();
    _tuiController = controller;
    _setTuiIo(controller);
    // Pending scheduled follow-ups light the indicator row on boot (#115).
    unawaited(_pushScheduledStatus());

    // The banner is part of the TUI output history so it stays visible above
    // the input line inside the alternate screen.
    await _printBanner();
    await _printViewerBannerIfAny();
    // The first _loadAgentContext() ran before the TUI owned the terminal —
    // its "found but disabled" hint never reached the transcript. Re-print.
    _printThirdPartySkillsDisabledHint();
    // Issue #503: the reconciliation notices paint BEFORE the history
    // replay — the replay is the final paint, so the resumed session's
    // tail (the last assistant message) stays on the first glass.
    // Wave-14 (#446): the anchor goes down BEFORE the summary — the boot
    // window starts at the summary + transcript region, and the banner
    // above rides the fold under the #827 indicator instead of pushing
    // the replayed tail's head off the glass.
    controller.markReplayAnchor();
    await _rehydrateJobBoard();

    await _replayRestoredSession();
    // One-time consent question for third-party skill roots: a TUI picker
    // over the first frame (Esc = "Not now", asked again next launch).
    // The visible-waiting row lights up on boot too (issue #450): armed
    // timers from previous runs + the restart-honesty note.
    unawaited(_waiting.push());
    // Consent first; the fresh-install wizard (issue #969) chains after it
    // so two wizard pickers never race for one answer completer.
    unawaited(
      _maybePromptSkillsAccess().then(
        (_) => _maybeStartFreshInstallProviderFlow(),
      ),
    );

    // An ambiguous `--session <name>` (same name in several folders or
    // several in one): the scoped choice picker over the first frame —
    // the auto-resolved session stays when dismissed.
    unawaited(_offerStartupSessionChoice());

    await controller.run();
    _setTuiIo(null);
    _tuiController = null;
  }

  /// Routes [io]'s output through the TUI controller while it runs (null
  /// detaches after the run).
  void _setTuiIo(FaTuiController? controller) {
    final tuiIo = io;
    if (tuiIo is _TuiCliIO) tuiIo._tui = controller;
  }

  /// Wires the TUI controller's callbacks to the line handler, pickers, and
  /// interrupt/steer paths.
  FaTuiController _createTuiController() {
    late final FaTuiController controller;
    controller = FaTuiController(
      mouseCapture: config.tuiMouseCapture,
      syncOutput: config.tuiSyncOutput,
      sttyRunner: config.sttyRunner,
      sigintPolicy: sigintPolicy,
      callbacks: FaTuiCallbacks(
        onSubmit: (line, {images = const []}) =>
            _handleTuiSubmit(controller, line, images),
        onModelSelected: _tuiSelectModel,
        buildSlashMenu: _buildSlashMenu,
        buildModelMenu: _buildModelMenu,
        statusLine: _statusLine,
        // The band composer (#806): the omp status line attaches as the
        // composer's top band unless the `tui.classic` kill switch pins
        // the legacy chrome (byte-identical rule + dim footer).
        statusSnapshot: config.tuiClassic ? null : _statusLineSnapshot,
        statusLineEngine: config.tuiClassic
            ? null
            : TuiStatusLine(spec: resolveStatusLineSpec(config.statusLine)),
        prompt: prompt,
        onInterrupt: () {
          if (isBusy) {
            // Marks the drain loop to discard queued messages (kimi-cli
            // drops the queue on cancel instead of starting new turns).
            _abortRequested = true;
            _abortRunOrCompaction();
          } else if (_activeCompactionAbort != null) {
            // Compaction-ONLY interrupt (issue #1085 round-2 review): a
            // bare /compact runs with isBusy false — Ctrl+C stops the
            // compaction while the session stays alive.
            _activeCompactionAbort?.cancel('interrupted by user');
          }
        },
        // Double-press Ctrl+C press 2 (issue #830): the same SIGINT-parity
        // exit the host's SIGINT handler runs — abort-if-running bounded,
        // session resume hint, exit 130.
        onCtrlCExit: onCtrlCExitRequest,
        isShiftPressed: config.isShiftPressed,
        opensPicker: (key) => const {
          '/sessions',
          '/mode',
          '/approval',
          '/provider',
          '/settings',
        }.contains(key),
        onPickerSelected: _tuiPickerSelected,
        onPickerCancelled: _tuiPickerCancelled,
        onSteer: _steerTuiMessages,
        pathCandidates: pathCandidatesFor,
        onHubAction: (action, key) => _onHubAction(action, key),
        readClipboardImage: () => readPasteboardImage(),
      ),
      isExited: () => _exited,
      programHooks: config.tuiProgramHooks,
    );
    return controller;
  }
}

            supported: true,
            url: status.url ?? settings.url,
            name: status.name ?? settings.name,
            agentId: status.agentId,
            channels: status.channels,
            connected: status.connected,
          );
        } on Object {
          // The plugin never started (opted out, or the connect failed):
          // report the resolved config without a live connection.
          return DapHubSnapshot(
            supported: true,
            url: settings.url,
            name: settings.name,
            channels: const [],
            connected: false,
          );
        }
      },
      onDapHubConfigChanged: ({url, name}) =>
          persistDapConfig(url: url, name: name, file: defaultDapConfigFile()),
      onModelChanged: (_) async {
        await persistConfig();
        await persistFolderModelState();
      },
      // `/provider` switches: redact an explicitly passed session token so
      // it cannot leak into tool results or session files, then persist the
      // new provider/model/baseUrl triple (never the key itself).
      onProviderChanged: (kind, key) async {
        if (key.isNotEmpty) {
          redactor.register('/provider token', key);
          redactionPipeline?.registerSecret(key);
          // A keyless startup never attached the redactor; a runtime token
          // still gets masked from here on.
          if (!redactorAttached) {
            attachSecretRedactor(cli.agent, redactor);
            redactorAttached = true;
          }
        }
        await persistConfig();
        await persistFolderModelState();
      },
      // `/key set` stored a secret: mask it from here on (same lazy attach).
      onSecretStored: (name, value) {
        redactor.register(name, value);
        redactionPipeline?.registerSecret(value);
        if (!redactorAttached && !redactor.isEmpty) {
          attachSecretRedactor(cli.agent, redactor);
          redactorAttached = true;
        }
      },
      // `request_secret` tool granted a secret: same redactor lazy attach.
      onSecretGranted: (name, value) {
        redactor.register(name, value);
        redactionPipeline?.registerSecret(value);
        if (!redactorAttached && !redactor.isEmpty) {
          attachSecretRedactor(cli.agent, redactor);
          redactorAttached = true;
        }
      },
      onModeChanged: (_) async => persistConfig(),
      onApprovalChanged: () async => persistConfig(),
      // Global `tools:` toggles (`/tools <id> global`): the CLI owns the
      // live scope; persistConfig writes it back (see below).
      onToolsConfigChanged: () async => persistConfig(),
      // Third-party skills consent (`skills:` config section): the startup
      // dialog and `/skills access` set it; shell `!`cmd`` injections in
      // skill bodies follow `disableShellExecution`.
      skillsAccess: saved.skillsAccess,
      skillsDisableShellExecution: saved.skillsDisableShellExecution,
      // Global per-skill toggles (`skills:` config section, issue #1151):
      // the CLI owns the live view; persistConfig writes it back.
      skillToggles: saved.skillToggles,
      onSkillsAccessChanged: (access) async {
        skillsAccess = access;
        await persistConfig();
      },
      onSkillTogglesChanged: () async => persistConfig(),
      // Shift+Enter in the TUI: HID polling when the startup gate allows
      // it (issue #355) — null over SSH, under FA_TUI_SHIFT_HID=0, after
      // a probe timeout, and on non-macOS hosts.
      isShiftPressed: hidShiftPressed,
      // Mouse capture is ON by default (wheel scrolls the session view —
      // in the alternate screen the terminal has no native scrollback, so
      // without capture two-finger scroll does nothing). FA_TUI_MOUSE=0
      // opts out for always-on native select-to-copy.
      tuiMouseCapture: _envNotFalsy('FA_TUI_MOUSE'),
      // DEC 2026 synchronized output: auto-detect by default; FA_TUI_SYNC
      // forces it on (terminals without DECRQM answers) or off (fallback).
      tuiSyncOutput: _envTristate('FA_TUI_SYNC'),
      // The omp band composer (#806): on unless `tui.classic: true` pins
      // the legacy chrome byte-identically.
      tuiClassic: saved.tuiClassic,
      statusLine: saved.statusLine,
      agentLoadMode: saved.agentLoadMode,
    ),
    io: io,
  );
  if (redactorAttached) attachSecretRedactor(cli.agent, redactor);

  // Issue #823: boot builds the queue runtime before the CLI (and its
  // quota service) exist — rebind once so depletion hints steer the
  // resolver from the first turn. No-op without a configured queue.
  await cli.attachProviderQueueQuotaFeed();

  persistConfig = () async {
    await saveCliConfig(
      home,
      CliConfig(
        // The provider/model triple is per-folder now (folder_model_state):
        // keep the LOADED seed in the global config so a `/model` or
        // `/provider` switch in one workspace never leaks into the others
        // across restarts — the switch persists through the folder's state
        // file instead, and explicit --model/--provider/--base-url still
        // win per launch.
        providerKind: saved.providerKind,
        modelId: saved.modelId,
        baseUrl: saved.baseUrl,
        mode: cli.currentMode.name,
        approvalMode: cli.approval.mode.label,
        allowedTools: cli.approval.alwaysAllowedTools,
        // Prompt overrides are static per session; keep the loaded raw map
        // so saving doesn't drop the section.
        promptOverrides: saved.promptOverrides,
        // Roles: the live resolver's config (a `/model` switch re-pins the
        // default chain, the settings-hub agent-models flow pins the
        // smol/subagent chains — possibly creating the resolver on demand).
        modelRoles: cli.config.modelRolesResolver?.config ?? saved.modelRoles,
        // TTSR rules are static per session; keep the loaded config so
        // saving doesn't drop the section.
        ttsr: saved.ttsr,
        // Saved custom providers (the live registry the CLI mutates).
        customProviders:
            cli.config.customProviders?.entries ?? saved.customProviders,
        // Models config (the live instance `/models set`/`remove` mutates).
        models: cli.config.modelsConfig ?? saved.models,
        // MCP servers (the live config — re-read on `/mcp reload`).
        mcp: cli.config.mcpConfig?.config ?? saved.mcp,
        // Third-party skills consent (mutable via the startup dialog and
        // `/skills access`); shell-execution policy is static per session.
        skillsAccess: skillsAccess,
        skillsDisableShellExecution: saved.skillsDisableShellExecution,
        // The live global `skills:` toggles (read from the loaded config,
        // updated by `/skills <name> global`); null before the first
        // resolution, in which case the loaded section is kept as-is.
        skillToggles: cli.globalSkillToggles ?? saved.skillToggles,
        // The saved cube default (the live value the Cube sandbox flow
        // rewrites; `saved.cube` keeps the section when nothing changed).
        cube: cli.config.cubeSettings ?? saved.cube,
        // The live global `tools:` scope (read at boot, updated by
        // `/tools <id> global`); null until the first availability
        // rebuild, in which case the loaded section is kept as-is
        // (project/runtime scopes stay live and are never persisted).
        tools: cli.globalTools ?? saved.tools,
        // The remaining static sections are carried through the save so
        // the whole-file rewrite cannot drop them (issue #288 audit); a
        // forgetful caller is additionally backstopped by saveCliConfig's
        // disk-block preservation. The compaction engine is deliberately
        // NOT carried: the settings-hub Compaction flow's session scope
        // promises "no file change", and its project/global scopes write
        // the yaml through the targeted upsert themselves — persisting
        // the live override here would leak a session (or project) pick
        // into ~/.fah/config.yaml on the next boot or change hook. The
        // on-disk `compaction:` block survives via the preservation
        // backstop instead.
        memory: saved.memory,
        redact: saved.redact,
        a2a: saved.a2a,
        providerTimeouts: saved.providerTimeouts,
        images: saved.images,
        fabric: saved.fabric,
        // Static per session: keep the loaded `power:` section so a save
        // never drops the user's sleep-prevention level.
        powerSleepPrevention: saved.powerSleepPrevention,
      ),
    );
  };

  try {
    await persistConfig();
  } on ConfigException catch (error) {
    // Issue #221 E3: an unparseable config.yaml makes the save refuse
    // loudly instead of clobbering the file with defaults. Keep running
    // with the in-memory config; the user's file stays untouched.
    stderr.writeln('warning: config not saved: $error');
  }

  Future<void> resetTerminalForShell() async {
    if (!stdin.hasTerminal) return;
    stdout.write('\x1b[?1000l\x1b[?1002l\x1b[?1003l\x1b[?1006l');
    stdout.write('\x1b[?1004l\x1b[?2004l');
    stdout.write('\x1b[?25h\x1b[?1049l');
    await stdout.flush();
    // Drain any pending terminal query/mouse responses so they don't echo
    // as garbage at the shell prompt.
    try {
      final drain = stdin.listen((_) {});
      await Future<void>.delayed(const Duration(milliseconds: 150));
      await drain.cancel();
    } on Object {
      // Nothing to drain.
    }
  }

  // Double-press Ctrl+C exit, interactive arm (issue #830): SIGINT-parity
  // teardown the TUI's ctrl+c press 2 also triggers via
  // [AgentCli.onCtrlCExitRequest] — abort-if-running bounded, session
  // resume hint, exit 130. The exit code is guaranteed: teardown steps
  // may not throw the caller into an unhandled-error death, so the whole
  // body runs under finally (the old single-press path's safety net).
  Future<void> exitInteractive130() async {
    try {
      terminalIo.resetRawMode();
      stdout.writeln();
      // Restore terminal modes (mouse tracking off, alt-screen exit,
      // cursor show) BEFORE exit(130) — otherwise the shell prompt
      // inherits mouse reporting and wheel scrolls print escapes.
      await resetTerminalForShell();
      if (cli.isBusy) {
        terminalIo.fireInterrupt();
        await cli.waitForIdle();
      }
      await cli.deleteSessionIfEmpty();
      // Real stdout, not io: the TUI is being torn down by this very
      // exit — an io-routed line would land in a dead transcript. A
      // session with nothing persisted prints the honest no-op line —
      // "resume this session with ..." would point at a deleted file.
      final hint = await cli.sessionResumeHint();
      stdout.writeln(hint ?? kNothingToResumeHint);
      await stdout.flush();
    } finally {
      exit(130);
    }
  }

  cli.onCtrlCExitRequest = () => unawaited(exitInteractive130());

  final sigintSub = ProcessSignal.sigint.watch().listen((_) {
    final wasBusy = cli.isBusy;
    switch (cli.sigintPolicy.press(
      headless: headlessPrompt != null || wireServe.wireServe,
    )) {
      case SigintAction.interruptAndStay:
        // Press 1 (issue #830): abort the in-flight run (bounded) and
        // STAY ALIVE — the next press inside the window exits. The TUI
        // gets the footer hint + idle-composer clear via the model; line
        // mode prints a dim stderr line.
        if (wasBusy) terminalIo.fireInterrupt();
        final tui = cli.tuiController;
        if (tui != null) {
          tui.armInterruptHint();
        } else {
          stderr.writeln(
            dimCtrlCExitHint(supportsAnsiEscapes: stdout.supportsAnsiEscapes),
          );
        }
      case SigintAction.exitInteractive:
        unawaited(exitInteractive130());
      case SigintAction.exitHeadless:
        // Headless graceful abort (issue #155): fire the interrupt, then
        // let the RUN settle — [AgentCli.waitForIdle] tracks the REPL's
        // settle future, which headless never starts, so the run future
        // itself is the honest wait: abort lands, the partial transcript
        // persists, the HEP writer emits `cancelled`, THEN exit 130.
        _gracefulHeadlessExit(terminalIo.fireInterrupt);
    }
  });
  // Backend supervisors send SIGTERM (issue #155): route it through the
  // same graceful abort as SIGINT — partial persist + `cancelled` frame +
  // exit 130 — instead of dying mid-write. A second SIGTERM escalates
  // (graceful → forced), the usual supervisor contract. [stdout.flush]
  // matters: exit() drops the async write buffer, taking the just-written
  // `cancelled` frame with it.
  if (headlessPrompt != null) {
    ProcessSignal.sigterm.watch().listen((_) {
      if (_sigtermSeen) exit(143);
      _sigtermSeen = true;
      _gracefulHeadlessExit(terminalIo.fireInterrupt);
    });
  }

  // `fa wire-serve` (issue #1103): headless Agent Wire Protocol v1
  // server. SIGINT/SIGTERM: both route through _gracefulHeadlessExit,
  // whose fireInterrupt aborts any in-flight run and whose
  // _wireServeSettle call ends the transport — runWireServe's finally
  // persists, and this branch's `exit(code)` continuation (registered
  // before _gracefulHeadlessExit's) wins the race: a graceful server
  // shutdown is a success, exit 0 (143 on a second SIGTERM, the usual
  // supervisor escalation).
  if (wireServe.wireServe) {
    var sigtermSeen = false;
    final sigtermSub = ProcessSignal.sigterm.watch().listen((_) {
      if (sigtermSeen) exit(143);
      sigtermSeen = true;
      _gracefulHeadlessExit(terminalIo.fireInterrupt);
    });
    final int code;
    try {
      code = await (_headlessRun = _runWireServeHost(
        cli: cli,
        wireServe: wireServe,
        terminalIo: terminalIo,
      ));
    } finally {
      await sigtermSub.cancel();
      await sigintSub.cancel();
      await stdout.flush();
      logTeeFile?.closeSync();
    }
    exit(code);
  }

  if (headlessPrompt != null) {
    _headlessRun = cli.runHeadless(
      attachReferences.isEmpty
          ? headlessPrompt
          // Non-image --attach files pass through as path references
          // appended to the prompt (issue #196).
          : '$headlessPrompt\n\n${attachReferences.join('\n\n')}',
      images: attachedImages,
      hep: hep,
      streamJson: streamJson,
      waitForJobs: effective.waitForJobs,
    );
    final int code;
    try {
      code = (await _headlessRun)!;
    } finally {
      await sigintSub.cancel();
      await stdout.flush();
      logTeeFile?.closeSync();
    }
    exit(code);
  }

  try {
    await cli.run();
  } finally {
    await sigintSub.cancel();
    logTeeFile?.closeSync();
  }

  // dart_tui's shutdown writes the reset sequences (?25h ?1049l ?1002l etc.)
  // and flushes stdout, but on some terminals the mouse-tracking disable
  // (?1002l ?1006l) arrives too late or is lost. Write them again here with
  await resetTerminalForShell();
  exit(0);
}

/// The executable used to wake asleep cross-session mailboxes: this
/// process's own path when it is a compiled snapshot, or null to fall back
/// to `fa` on PATH (a `dart run` VM cannot be re-spawned with session
/// args).
String? wakeExecutable() {
  final exe = Platform.script.toFilePath();
  final base = exe.split(Platform.pathSeparator).last.toLowerCase();
  if (base == 'dart' || base == 'dart.exe') return null;
  return exe;
}

/// `fa wire-serve` transport host (issue #1103). WS mode: binds the
/// loopback port early (fail fast on an occupied port), and prints the
/// one-time startup line only AFTER the boot — and its lease gate —
/// succeeded ([runWireServe]'s `onReady`), so a parent never reads a
/// startup line for a serve that refuses to boot. stdio mode: NDJSON
/// over stdin/stdout, no startup line. Shutdown triggers: stdin EOF and
/// SIGTERM (routed through [_wireServeSettle]) — BOTH transports race
/// the shutdown trigger, so a signal never strands the teardown; boot,
/// persist, and teardown live in [AgentCli.runWireServe].
Future<int> _runWireServeHost({
  required AgentCli cli,
  required WireServeArgs wireServe,
  required _TerminalCliIO terminalIo,
}) async {
  // --token T is visible in the process list; the env var keeps it out
  // of `ps` for hosts that prefer that (review #1113 r2, suggestion #5).
  final token =
      wireServe.token ??
      () {
        final fromEnv = Platform.environment['FA_WIRE_SERVE_TOKEN'];
        return (fromEnv == null || fromEnv.isEmpty)
            ? wireServeToken()
            : fromEnv;
      }();
  HttpServer? http;
  if (!wireServe.stdio) {
    try {
      // AC20: a port race is a LOUD startup failure naming the port —
      // never a silent fallback.
      http = await bindLoopback(wireServe.port ?? 0);
    } on SocketException catch (error) {
      _fail('wire-serve: cannot bind 127.0.0.1:${wireServe.port ?? 0}: $error');
    }
  }
  final shutdown = Completer<void>();
  _wireServeSettle = () {
    if (!shutdown.isCompleted) shutdown.complete();
  };
  // WS mode: a supervisor closing our stdin pipe also ends the serve
  // (documented in docs/wire-protocol.md §8). The stdio transport owns
  // stdin itself in --stdio mode. A stdin ERROR is transport death, not
  // silence: log it, then end the serve through the same graceful settle
  // (review #1113 r4 — loud, never silent).
  StreamSubscription<void>? stdinSub;
  if (http != null) {
    stdinSub = stdin.listen(
      (_) {},
      onDone: _wireServeSettle!,
      onError: (Object error) {
        stderr.writeln('wire-serve: stdin failed: $error');
        _wireServeSettle!();
      },
    );
  }
  try {
    final code = await cli.runWireServe(
      onReady: http == null
          ? null
          : () => writeStartupLine(
              WireServeStartupLine(port: http!.port, token: token),
            ),
      serve: (server) async {
        if (wireServe.stdio) {
          final done = serveStdio(server);
          // stdin EOF is the natural end; a signal-completed shutdown
          // must ALSO end the serve, or the graceful teardown waits out
          // its full settle window and the persist never runs (review
          // #1113 r2, #3).
          await Future.any([shutdown.future, done]);
          // The race's loser still runs — surface a late transport
          // failure (e.g. EPIPE on stdout mid-teardown) instead of the
          // silent drop a bare `ignore()` would be (review #1113 r4).
          unawaited(
            done.catchError((Object error) {
              stderr.writeln('wire-serve: stdio transport failed: $error');
            }),
          );
          return;
        }
        final listenDone = httpListen(http!, server, token);
        await Future.any([shutdown.future, listenDone]);
        await http!.close(force: true);
      },
      onDiagnostic: (line) => stderr.writeln(line),
    );
    // Resume hint on stderr — stdout is the protocol channel.
    final hint = await cli.sessionResumeHint();
    if (hint != null) stderr.writeln(hint);
    return code;
  } finally {
    _wireServeSettle = null;
    await stdinSub?.cancel();
    await http?.close(force: true);
  }
}

/// The wire-serve CLI io: a silent sink. Every rendered line dies here so
/// nothing TUI-shaped can reach the protocol stream; writeln keeps stderr
/// for diagnostics. Never interactive — the constructor's null ask/secret
/// callbacks are replaced by the wire surfaces at boot.
final class _WireServeSilentCliIO implements CliIO {
  final _interrupts = StreamController<void>.broadcast();

  @override
  Stream<String> get lines => const Stream<String>.empty();

  @override
  Stream<void> get interrupts => _interrupts.stream;

  @override
  Stream<KeyEvent> get keys => const Stream<KeyEvent>.empty();

  @override
  bool get supportsRawMode => false;

  @override
  bool get isInteractive => false;

  @override
  int get columns => 80;

  @override
  int get rows => 24;

  @override
  void write(String text) {}

  @override
  void writeln(String text) => stderr.writeln(text);
}

  /// Capability-gated tool availability (issue #19) — state for the
  /// `agent_cli_tools.dart` extension: the static tool set grouped by
  /// availability id (the `read` group entry swaps in place on sqlite
  /// toggles so the gate always re-registers the current variant), the
  /// enforcing gate (one per CLI — the wrapped executor captures it), the
  /// shared read/edit hashline snapshot store, the tools' execution env,
  /// and the scope caches.
  late final Map<String, List<AgentTool>> _toolGroupsById;
  late final ToolAvailabilityGate _toolGate;
  late final HashlineSnapshotStore _snapshotStore;
  late final SessionVarsExecutionEnv _coreToolEnv;
  final _ToolsWiringState _toolsWiring = _ToolsWiringState();

  /// The LIVE tool-load preset (issue #680): [AgentCliConfig.loadMode] at
  /// boot; the settings hub's load-mode flow re-assigns it and rebuilds
  /// availability, so a mid-session switch recomposes the schema+prompt.
  AgentLoadMode _liveLoadMode = AgentLoadMode.defaultMode;

  /// Long-term memory controller (project + user scope stores). Always
  /// constructed; search is disabled when no LLM provider is injected.
  late final MemoryController _memory;
  late final CheckpointRewindController _checkpoints;

  /// The `compact_expand` controller (issue #148): per-turn expand budget
  /// reset + tool binding to the LIVE session.
  late final CompactExpandController _compactExpand;
  TtsrController? _ttsr;
  final _Style _style;
  final bool _useTui;
  final String _version;

  /// The markdown→terminal policy every non-TUI surface renders assistant
  /// text through at message end (issue #774). Defaults to raw
  /// passthrough; bin/fah resolves TTY/color/width for the real surfaces.
  final MarkdownSurface _markdownSurface;

  /// The streamed answer of the current assistant message on non-TUI
  /// surfaces (issue #774): line mode and headless cannot repaint, so the
  /// message buffers here and renders once, whole, at message end.
  final StringBuffer _assistantText = StringBuffer();

  /// Whether the default role resolved and drives the agent (roles mode).
  /// The banner's key-status line reads env var names from the live model's
  /// provider then; legacy mode reads them from the provider kind.
  var _rolesDriven = false;
  final _usage = UsageAccumulator();

  // Issue #277 hub driver state (see agent_hub_cli.dart): the projection
  // accumulates running spans; the panel log keeps deferred (btw) history;
  // lazy subscriptions keep task-block rendering for hub-less sessions.
  final AgentHubProjection _hubProjection = AgentHubProjection();
  final DeferredPanelLog _hubPanels = DeferredPanelLog();

  /// Issue #429: per-session background-job board (truthful phases,
  /// per-turn collapse, reload records) — replaced wholesale on resume.
  ShellJobBoard _jobBoard = ShellJobBoard();

  /// Registry-persist serialization tail (issue #539; see `_persistJobBoard` in the driver).
  Future<void> _persistChain = Future.value();
  final DateTime _hubMainStartedAt = DateTime.now();
  String? _hubTranscriptId;
  Timer? _hubFollowTimer;
  StreamSubscription<dynamic>? _hubSubagentEventsSub;
  StreamSubscription<dynamic>? _hubTaskStartsSub;

  /// Hub tree `mail:N` marker counts (async peek → refresh-only re-push
  /// by the driver extension, which cannot hold fields — state here).
  final Map<String, int> _hubMailCounts = <String, int>{};
  bool _hubMailRefreshInFlight = false;

  // Issue #437 steering delivery: a steer persists at accept and queues
  // here until the loop merges it at a step boundary (identity match) or
  // the settle leftover drops it; wake paths deliver recovered records.
  final List<PendingSteering> _pendingSteering = [];

  /// Last agent event time — the run heartbeat. A busy run silent past
  /// `config.steeringStaleAfter` looks wedged: steering flips to `dead`.
  DateTime? _lastAgentEventAt;

  /// Recovered steering from the previous session (persisted-but-
  /// unconsumed records), awaiting the idle wake; null once delivered.
  List<({String recordId, String text, DeferredPanel panel})>?
  _recoveredSteering;

  /// Guards the recovery wake against the settle-gap re-entry (mirrors
  /// `_inboxWakeRunning`).
  bool _steeringWakeRunning = false;

  /// Hard bounds for the compaction-time memory extraction (see
  /// `_runAutoCompact`): cancel the extraction stream after 90s, and
  /// force-skip after 120s even if the cancel didn't land.
  static const _memoryExtractionDeadline = Duration(seconds: 90);
  static const _memoryExtractionHardCap = Duration(seconds: 120);

  /// Memoized settled-part context estimate for the status line
  /// (see `_liveContextTokens` in approval_commands.dart): keyed on the
  /// transcript length + last message instance — never on stream content.
