/// The `FA_PROVIDERS` dart-define value: a comma-separated allowlist of
/// provider names, `all`/empty for everything. Compile-time constant so
/// filtered-out adapters still tree-shake out of a `dart compile` build.
/// Set via the CI/build system: the native-binaries workflow passes it as
/// `-DFA_PROVIDERS=...` on the compile step.
const _faProvidersDefine = String.fromEnvironment('FA_PROVIDERS');

/// The runtime `FA_PROVIDERS` environment variable, resolved by the host
/// (bin/fah.dart or the app wiring) and injected once at startup. The
/// compile-time define WINS over this runtime value when both are set.
/// Unset (`null`) on hosts without a concept of process env (web).
String? providerFilterEnvOverride;

/// Whether [name] survives the provider filter (see [providerCatalog]).
/// `true` for every name without a filter.
///
/// Filter precedence: the `FA_PROVIDERS` dart-define first (immutable,
/// tree-shakable), then the runtime env override ([providerFilterEnvOverride],
/// set from the process environment by the host at startup). Values: an
/// empty/`all`/`*` value keeps every provider; anything else is a
/// comma-separated name allowlist.
bool providerEnabledInBuild(String name) {
  final define = _faProvidersDefine.isNotEmpty
      ? _faProvidersDefine
      : (providerFilterEnvOverride ?? '');
  if (define.isEmpty || define == 'all' || define == '*') return true;
  final allowed = define
      .split(',')
      .map((s) => s.trim().toLowerCase())
      .where((s) => s.isNotEmpty);
  return allowed.contains(name.trim().toLowerCase());
}

/// The build-enabled subset of the catalog (insertion order preserved).
/// Without `FA_PROVIDERS` this is the whole table; `visible: false`
/// entries are excluded regardless of the filter.
List<ProviderSpec> enabledProviders() => [
  for (final spec in providerCatalog.values)
    if (spec.visible && providerEnabledInBuild(spec.name)) spec,
];

/// The build-enabled provider names (`enabledProviders` in name form).
List<String> enabledProviderNames() => [
  for (final spec in enabledProviders()) spec.name,
];

/// Provider base URLs the CLI can show WITHOUT any user config — the
/// catalog's default endpoints above. The cli_visual leak guard subtracts
/// these from the real-config markers so a hermetic screen rendering the
/// provider picker is never flagged for bundled-catalog content
/// (issue #508).
Set<String> get bundledCatalogEndpoints => {
  for (final spec in enabledProviders())
    if (spec.defaultBaseUrl.isNotEmpty) spec.defaultBaseUrl,
};

/// Resolves [name] against the [providerCatalog], honoring the build-time
/// provider filter (`FA_PROVIDERS` — filtered names resolve to null and the
/// error paths list only the enabled providers).
///
/// The legacy CLI kind `openai-completions` is accepted as an alias for
/// `openrouter` (its historical default endpoint).
ProviderSpec? catalogProvider(String name) {
  final normalized = name.trim().toLowerCase();
  if (normalized == 'openai-completions' &&
      providerEnabledInBuild('openrouter')) {
    return providerCatalog['openrouter'];
  }
  final spec = providerCatalog[normalized];
  if (spec == null || !providerEnabledInBuild(spec.name)) return null;
  return spec;
}

/// The Anthropic API dialect family the Claude ceiling table was derived
/// from: the table is only consulted for models riding this api — a claude
/// id served over any other dialect (openrouter routing, a claude-named
/// model on an OpenAI-compatible proxy) keeps its provider's own default.
const anthropicMessagesApi = 'anthropic-messages';

/// Per-family maximum OUTPUT token ceilings for Claude models, ported from
/// kimi-code's `_modelOutputCeilings` (issue #273): `family ->
/// 'major.minor' -> maxOutputTokens`. Anthropic raised output caps from
/// 4096 (3.x) through 32768/64000 (4.x) to 128000 (4.6+), but the provider
/// specs' blanket `maxTokens: 16384` clamps every model to the old floor;
/// this table is the per-model correction.
const _modelOutputCeilings = <String, Map<String, int>>{
  'opus': {
    '3.0': 4096,
    '4.0': 32768,
    '4.1': 32768,
    '4.5': 64000,
    '4.6': 128000,
    '4.7': 128000,
    '4.8': 128000,
  },
  'sonnet': {
    '3.0': 4096,
    '3.5': 8192,
    '3.7': 8192,
    '4.0': 64000,
    '4.1': 64000,
    '4.2': 64000,
    '4.3': 64000,
    '4.4': 64000,
    '4.5': 64000,
    '4.6': 128000,
    '5.0': 128000,
  },
  'haiku': {'3.0': 4096, '3.5': 8192, '4.5': 64000},
};

/// Conservative fallback for a Claude model the table cannot pin (kimi-code's
/// unknown-fallback): allow the largest documented cap and let the API
/// reject, rather than silently truncating a modern response at 16384.
const int _unknownClaudeOutputCeiling = 128000;

/// The ceiling-table step of max-output-token resolution for [modelId]:
/// per-model config override (caller-side) > this table > provider default
/// (caller-side). Null is the table MISS — non-`claude` ids (glm, kimi,
/// ...) ride the caller's provider default unchanged, and so does any
/// `claude` id whose [api] is outside the table's family
/// ([anthropicMessagesApi], issue #302: Claude-specific ceilings never
/// leak onto other provider families).
///
/// Ported from kimi-code (issue #273). Resolution over the normalized id
/// (lowercased, `_` → `-`):
/// - no `claude` substring → null;
/// - family (`opus`|`sonnet`|`haiku`) + version, from two regexes:
///   (a) version AFTER the family:
///   `(?:^|-)(opus|sonnet|haiku)(?:-?(\d{1,2})(?:[.-](\d{1,2}))?(?=[-.]|$))?`
///   — `claude-opus-4-5-20251101` → (4,5), `claude-opus-4.5` → (4,5),
///   `claude-opus-4` → (4,0); the `\d{1,2}` + `[-.]|$` lookahead rejects
///   date suffixes (`claude-3-opus-20240229` never parses `20240229`);
///   (b) no version from (a): one BEFORE the family, matched over the text
///   preceding it with `(\d{1,2})(?:[.-](\d{1,2}))?(?=-|$)` —
///   `claude-3-opus` → (3,0), `claude-3-5-sonnet` → (3,5);
/// - the largest catalogued (major,minor) ≤ the parsed version wins (an
///   exact hit is that maximum, so one scan serves both: opus-4.9 rides
///   4.8's 128000, sonnet-4.7 falls to 4.6's); nothing catalogued ≤ it, an
///   unparseable version, or no known family → [_unknownClaudeOutputCeiling]
///   (AC2: totally unknown Claude → conservative fallback).
int? resolveModelMaxOutputTokens(String modelId, {required String api}) {
  if (api != anthropicMessagesApi) return null;
  final id = modelId.toLowerCase().replaceAll('_', '-');
  if (!id.contains('claude')) return null;

  final match = RegExp(
    r'(?:^|-)(opus|sonnet|haiku)(?:-?(\d{1,2})(?:[.-](\d{1,2}))?(?=[-.]|$))?',
  ).firstMatch(id);
  if (match == null) return _unknownClaudeOutputCeiling;
  final table = _modelOutputCeilings[match.group(1)!]!;

  int major;
  int minor;
  final after = match.group(2);
  if (after != null) {
    major = int.parse(after);
    minor = match.group(3) == null ? 0 : int.parse(match.group(3)!);
  } else {
    final before = RegExp(
      r'(\d{1,2})(?:[.-](\d{1,2}))?(?=-|$)',
    ).firstMatch(id.substring(0, match.start));
    if (before == null) return _unknownClaudeOutputCeiling;
    major = int.parse(before.group(1)!);
    minor = before.group(2) == null ? 0 : int.parse(before.group(2)!);
  }

  // Largest catalogued version ≤ the parsed one; monotonic
  // `major*100+minor` keys keep the comparison integer-simple.
  final given = major * 100 + minor;
  int? bestCeiling;
  var bestVersion = -1;
  for (final entry in table.entries) {
    final dot = entry.key.indexOf('.');
    final version =
        int.parse(entry.key.substring(0, dot)) * 100 +
        int.parse(entry.key.substring(dot + 1));
    if (version > given) continue;
    if (version > bestVersion) {
      bestVersion = version;
      bestCeiling = entry.value;
    }
  }
  return bestCeiling ?? _unknownClaudeOutputCeiling;
}

/// RFC 7230 token bytes — everything an HTTP header NAME may carry. A name
/// outside this set either carries whitespace (`x api key`) or injects a
/// CRLF into the request head (`x-api-key\r\nX-Evil: 1`), so both are
/// rejected at config parse, not on the wire (issue #964 AC5).
final _authHeaderNamePattern = RegExp(r"^[A-Za-z0-9!#$%&'*+\-.^_`|~]+$");

/// Parses the optional `authHeader:` yaml value into a header name. Null
/// stays null (the `Authorization: Bearer` default); anything that is not a
/// non-empty RFC 7230 token throws [ConfigException] naming [where] — the
/// config entry that owns the value.
String? parseAuthHeaderName(Object? value, String where) {
  if (value == null) return null;
  final name = value is String ? value.trim() : '';
  if (!_authHeaderNamePattern.hasMatch(name)) {
    throw ConfigException(
      '$where: invalid authHeader "$value" — expected an HTTP header name '
      "(letters, digits, !#\$%&*+-.^_`|~), e.g. x-api-key",
    );
  }
  return name;
}

/// The adapter kinds whose stream function routes through
/// [streamOpenAICompletions] — the only wire that reads
/// [Model.authHeader]. `dial` carries its own transport with a hardcoded
/// `Api-Key` header, and `copilot`/`chatgpt-codex` authenticate via OAuth
/// — all three speak openai-completions-shaped APIs (`spec.api`) but
/// ignore the field, so a config-declared authHeader on them is rejected
/// loudly instead of silently dropped (issue #964 round-2 review).
const _authHeaderAdapterKinds = {
  'openai-completions',
  'minimax',
  'zai',
  'aiin',
};

/// Rejects a config-declared `authHeader` on a provider whose adapter does
/// not read the field (issue #964 review): only the OpenAI-completions
/// adapter family honors it — everywhere else the header would be silently
/// ignored. A null [spec] (provider unknown at parse time — roles chain
/// entries skip unknown providers at resolve) passes; nothing reaches a
/// builder for it.
void validateAuthHeaderDialect(
  String? authHeader,
  ProviderSpec? spec,
  String where,
) {
  if (authHeader == null ||
      spec == null ||
      _authHeaderAdapterKinds.contains(spec.kind)) {
    return;
  }
  throw ConfigException(
    '$where: authHeader only applies to the OpenAI-completions adapter '
    '(openai-completions, minimax, zai, aiin) — provider "${spec.name}" '
    'routes to the ${spec.kind} adapter, which ignores it',
  );
}

/// Builds a [Model] for [provider]/[modelId] with catalog defaults, overrid-
/// able per reference (see `ModelRef`).
///
/// `maxTokens` resolution order: the explicit override, then the Claude
/// ceiling table ([resolveModelMaxOutputTokens]), then the provider spec
/// default — per-model reality beats the blanket 16384.
///
/// Throws [ConfigException] for unknown providers.
Model buildCatalogModel(
  String provider,
  String modelId, {
  String? baseUrl,
  int? contextWindow,
  int? maxTokens,
  List<String>? input,
  String? thinkingLevel,
  String? authHeader,
}) {
  final spec = catalogProvider(provider);
  if (spec == null) {
    throw ConfigException(
      'unknown provider "$provider" — supported providers: '
      '${providerCatalog.keys.join(', ')}',
    );
  }
  validateAuthHeaderDialect(authHeader, spec, 'provider "$provider"');
  return Model(
    id: modelId,
    name: modelId,
    api: spec.api,
    provider: spec.name,
    baseUrl: baseUrl ?? spec.defaultBaseUrl,
    reasoning: spec.reasoning,
    input: input ?? spec.input,
    thinkingLevel: thinkingLevel,
    contextWindow: contextWindow ?? spec.contextWindow,
    maxTokens:
        maxTokens ??
        resolveModelMaxOutputTokens(modelId, api: spec.api) ??
        spec.maxTokens,
    authHeader: authHeader,
  );
}

/// Providers carry NO default model: a model is always an explicit choice
/// (`--model`, a saved switch, a roles chain, or a picker's live `/models`
/// list). Silent defaults chose paid flagships over free tiers behind the
/// user's back (zai's `glm-5.3` vs `glm-5.3-flash` — real spend nobody
/// ordered), so the mechanism was removed, not re-seeded.
///
/// Resolves a CLI provider [kind] or catalog name to its [ProviderSpec]
/// for the legacy single-model boot path. The lookup is catalog-driven:
/// every [providerCatalog] entry is reachable by its name AND its adapter
/// kind, so a catalog addition can never again leave the boot switch
/// behind and brick the CLI with `ConfigException: unknown provider`
/// (issue #760 — the app wrote `provider: chatgpt-codex`, the hand-maint-
/// ained switch did not know the kind). Returns `null` for ids no version
/// knows; the config boundary degrades those (warn + fallback) instead of
/// throwing.
///
/// Historical behavior preserved: `openai-completions`/`openrouter` with
/// a custom [baseUrl] resolve to the `openai` spec (the model reports
/// provider `openai` instead of `openrouter`); without one, `openrouter`.
///
/// Intentionally filter-less by default: the boot restore path must judge
/// every persisted id against the full catalog — a disabled-in-this-build
/// saved provider restores and boots (the wire adapters stay in the
/// binary) instead of degrading to the fallback warning. User-facing
/// surfaces (pickers, roles, `/provider`, key collection, `models:`
/// validation) pass `honorBuildFilter: true` — the filter the
/// [catalogProvider] lookups used to apply — instead of re-wiring
/// [providerEnabledInBuild] by hand.

/// The legacy `openai-completions`/`openrouter` default-endpoint rule
/// (gh-760 historical behavior): the model reports provider `openai`
/// instead of `openrouter` on a custom base URL.
ProviderSpec? _legacyOpenAiSpec(String? baseUrl) =>
    baseUrl == null ? providerCatalog['openrouter'] : providerCatalog['openai'];

/// The kind scan: the entry whose ADAPTER KIND is [key] — a kind that is
/// not itself a catalog name (e.g. `chatgpt-codex`).
ProviderSpec? _kindScan(String key) {
  for (final spec in providerCatalog.values) {
    if (spec.kind == key) return spec;
  }
  return null;
}

/// The FA_PROVIDERS gate for resolved specs: a [honorBuildFilter] lookup
/// yields null when the resolved entry is disabled in this build.
ProviderSpec? _applyBuildFilter(ProviderSpec? spec, bool honorBuildFilter) {
  if (spec == null) return null;
  if (honorBuildFilter && !providerEnabledInBuild(spec.name)) return null;
  return spec;
}

ProviderSpec? resolveCliProviderSpec(
  String kind, {
  String? baseUrl,
  bool honorBuildFilter = false,
}) {
  // Uniform normalization: names AND kinds are lowercase in the catalog,
  // so the literal special-case, the name leg, and the kind leg all
  // accept case variants identically.
  final key = kind.trim().toLowerCase();
  if (key == 'openai-completions' || key == 'openrouter') {
    return _applyBuildFilter(_legacyOpenAiSpec(baseUrl), honorBuildFilter);
  }
  return _applyBuildFilter(
    providerCatalog[key] ?? _kindScan(key),
    honorBuildFilter,
  );
}

/// The canonical PERSISTED identity for a provider id (issue #772): the
/// catalog entry's adapter [ProviderSpec.kind]. Config files
/// (`provider:`, folder model state, handoffs) carry the kind — the name
/// (`chatgpt`) is display/command sugar that resolves here, in ONE place.
///
/// Only UNIQUE-kind entries canonicalize: when several catalog entries
/// share one kind (`openai-completions` is openrouter/openai/kimi/codemie),
/// the kind is coarser than the saved name and the name stays (the endpoint
/// base URL carries the identity there). A kind owned by exactly one entry
/// (`chatgpt-codex` → `chatgpt`) folds its name-shaped spellings onto the
/// kind. Alias spellings (`chatgpt.com`) fold first via
/// [canonicalProviderName] at the config boundary. Unknown ids return
/// unchanged — the boot boundary warns and degrades (issue #760), it never
/// rewrites a value it cannot resolve.
String canonicalProviderKind(String id) {
  final spec = resolveCliProviderSpec(id);
  if (spec == null) return id;
  for (final other in providerCatalog.values) {
    if (other.kind == spec.kind && other.name != spec.name) return id;
  }
  return spec.kind;
}

/// Builds the legacy single [Model] the `fah` executable runs when no roles
/// are configured (`--provider`/`--model`/`--base-url` flags).
///
/// Resolves through [resolveCliProviderSpec] — every catalog name and kind
/// builds; an id no version knows throws [ConfigException] (direct API
/// callers get the loud error, the boot config boundary degrades it).
/// `maxTokens` resolves like [buildCatalogModel]: ceiling table
/// ([resolveModelMaxOutputTokens]) first, provider spec default on a miss.
Model buildCliDefaultModel(
  String providerKind, {
  String? modelId,
  String? baseUrl,
  List<String>? input,
  String? thinkingLevel,
  String? authHeader,
}) {
  final spec = resolveCliProviderSpec(providerKind, baseUrl: baseUrl);
  if (spec == null) {
    throw ConfigException('unknown provider: $providerKind');
  }
  validateAuthHeaderDialect(authHeader, spec, 'provider "$providerKind"');

  final id = modelId;
  if (id == null) {
    // No provider has a default model — the choice is always explicit.
    throw ConfigException('provider "$providerKind" requires --model <id>');
  }
  final maxTokens =
      resolveModelMaxOutputTokens(id, api: spec.api) ?? spec.maxTokens;
  return Model(
    id: id,
    name: id,
    api: spec.api,
    provider: spec.name,
    baseUrl: baseUrl ?? spec.defaultBaseUrl,
    reasoning: spec.reasoning,
    input: input ?? spec.input,
    // The FA_PROVIDER_* preconfig level rides the fallback/default model
    // when no roles chain pins it (issue #734 rework: the boot notice must
    // never name a level the booted model does not carry).
    thinkingLevel: thinkingLevel,
    contextWindow: spec.contextWindow,
    maxTokens: maxTokens,
    // Folder-state restores adopt the matching saved entry's authHeader
    // (issue #964) — a restored gateway endpoint without its header 401s.
    authHeader: authHeader,
  );
}

/// Builds the [StreamFunction] for a provider adapter [kind]
/// (`openai-completions`, `minimax`, `zai`, `anthropic`, `google`, `dial`,
/// `chatgpt-codex`, `copilot`)
/// with a static [apiKey]. Throws [ConfigException] for unknown kinds.
///
/// [sessionId] (resolved lazily per call) is the prompt-cache affinity key
/// threaded to adapters that support one (OpenAI `prompt_cache_key`,
/// OpenRouter `x-session-id`); [cacheRetention] sets the adapters' cache
/// retention (`short`/`long`/`none`, adapter default when null). Both are
/// defaults: an active [StreamCacheRouting] override (the compaction
/// bypass) wins per call. [dialApiVersion] is the DIAL `api-version` query
/// parameter (the `dial` kind only; omitted when null).
StreamFunction providerStreamFunction(
  String kind,
  String apiKey, {
  String? Function()? sessionId,
  String? cacheRetention,
  String? dialApiVersion,
  bool? dialCacheMarkersSupported,
  ChatGptCredentialsPersist? onChatGptCredentialsRefreshed,
}) {
  if (kind != 'openai-completions' &&
      kind != 'anthropic' &&
      kind != 'google' &&
      kind != 'dial' &&
      kind != 'minimax' &&
      kind != 'zai' &&
      kind != 'aiin' &&
      kind != 'chatgpt-codex' &&
      kind != 'copilot') {
    throw ConfigException('Unknown provider kind: $kind');
  }
  // ignore: implicit_call_tearoffs
  final inner = _CatalogStreamFunction(
    kind,
    apiKey,
    sessionId,
    cacheRetention,
    dialApiVersion,
    dialCacheMarkersSupported,
    onChatGptCredentialsRefreshed,
  );
  // Every provider call (chat turns, compaction summaries, memory
  // extraction, media) rides the transient-network retry: a Wi-Fi switch
  // mid-turn dies with "Connection reset by peer" — sleep, replay.
  return transientRetryStreamFunction(inner.call);
}

/// The [providerStreamFunction] product: resolves the cache routing at call
/// time — an active [StreamCacheRouting] override first, then the factory
/// defaults — and builds the adapter options for one call.
final class _CatalogStreamFunction {
  const _CatalogStreamFunction(
    this._kind,
    this._apiKey,
    this._sessionId,
    this._cacheRetention,
    this._dialApiVersion,
    this._dialCacheMarkersSupported,
    this._onChatGptCredentialsRefreshed,
  );

  final String _kind;
  final String _apiKey;
  final String? Function()? _sessionId;
  final String? _cacheRetention;
  final String? _dialApiVersion;
  final bool? _dialCacheMarkersSupported;
  final ChatGptCredentialsPersist? _onChatGptCredentialsRefreshed;

  /// The [StreamFunction] entry point.
  AssistantMessageEventStream call(
    Model model,
    Context context, {
    CancelToken? cancelToken,
  }) {
    final routing = StreamCacheRouting.current;
    final effectiveSessionId = routing?.sessionId ?? _sessionId?.call();
    final effectiveRetention = routing?.cacheRetention ?? _cacheRetention;
    return switch (_kind) {
      'openai-completions' ||
      'minimax' ||
      'zai' ||
      'aiin' => streamOpenAICompletions(
        model,
        context,
        OpenAICompletionsOptions(
          apiKey: _apiKey,
          cancelToken: cancelToken,
          sessionId: effectiveSessionId,
          cacheRetention: effectiveRetention,
        ),
      ),
      'anthropic' => streamAnthropic(
        model,
        context,
        AnthropicOptions(
          apiKey: _apiKey,
          cancelToken: cancelToken,
          cacheRetention: effectiveRetention,
        ),
      ),
      'google' => streamGoogle(
        model,
        context,
        GoogleOptions(apiKey: _apiKey, cancelToken: cancelToken),
      ),
      'dial' => streamDial(
        model,
        context,
        DialOptions(
          apiKey: _apiKey,
          apiVersion: _dialApiVersion,
          cancelToken: cancelToken,
          sessionId: effectiveSessionId,
          cacheRetention: effectiveRetention,
          cacheMarkersSupported: _dialCacheMarkersSupported,
        ),
      ),
      'copilot' => streamCopilot(
        model,
        context,
        CopilotOptions(
          githubToken: _apiKey,
          cancelToken: cancelToken,
          sessionId: effectiveSessionId,
          cacheRetention: effectiveRetention,
        ),
      ),
      'chatgpt-codex' => streamChatGptCodex(
        model,
        context,
        credentials: _apiKey,
        onCredentialsRefreshed: _onChatGptCredentialsRefreshed,
        cancelToken: cancelToken,
      ),
      // Validated by providerStreamFunction; unreachable.
      _ => throw ConfigException('Unknown provider kind: $_kind'),
    };
  }
}

/// The provider/key management section of [AgentCli]: the `/provider` and
/// `/key` commands, the guided custom-provider flow glue, the TUI provider
/// picker, and the key-status helpers. Split out of `agent_cli.dart` to
/// keep that file under the repo's 2800-line size gate. Same library (a
/// `part of`), so the extension sees the class's private members.
part of 'agent_cli.dart';

/// Implementation members of [AgentCli] for provider and key management.
extension on AgentCli {
  /// Starts the guided custom-provider setup (or edit, when the `initial*`
  /// prefills and [editName] are set) without awaiting it: the REPL loop
  /// must keep reading lines so the flow's prompts can be answered
  /// (awaiting it here would deadlock the loop on the first question).
  Future<void>? _startProviderFlow({
    String? initialType,
    String? initialBaseUrl,
    String? initialName,
    String? initialModelId,
    String? editName,
    ({String label, Future<String?> Function() run})? reauth,
  }) {
    if (_providerFlowActive) return null;
    _providerFlowActive = true;
    // The future is surfaced (line-mode fresh-install redraw chains on it)
    // while staying fire-and-forget for every slash-command caller: the
    // REPL loop must keep reading lines so the flow's prompts can be
    // answered (awaiting it would deadlock the loop on the first question).
    final done =
        runCustomProviderFlow(
          io,
          CustomProviderFlowConfig(
            askLine: _askLine,
            pickOption: _pickOption,
            fetchModels: _fetchModelsForFlow,
            applyResult: (setup) =>
                _applyCustomProviderSetup(setup, editName: editName),
            currentModelId: () => _agent.state.model.id,
            rolesActive: config.modelRolesResolver != null,
            deriveName: (baseUrl) =>
                config.customProviders?.deriveName(baseUrl) ?? 'custom',
            initialType: initialType,
            initialBaseUrl: initialBaseUrl,
            initialName: initialName,
            initialModelId: initialModelId,
            editName: editName,
            reauth: reauth,
          ),
        ).whenComplete(() {
          _providerFlowActive = false;
          // Leftover buffered lines are flow answers, not user prompts.
          _promptLineBuffer.clear();
        });
    unawaited(done);
    return done;
  }

  /// Fresh-install gate (issue #969): the executable flagged a REPL boot
  /// with nothing configured and no key anywhere — open the same guided
  /// add-provider wizard `/provider custom` opens, before the first
  /// prompt, so the user adds a provider instead of staring at the
  /// default provider's "no key set" noise. Fire-and-forget like every
  /// flow start: the REPL loop answers the prompts. Piped input (and
  /// headless, which never gets the flag) never enters the wizard.
  /// Returns the wizard's future (null when the boot is not fresh) so the
  /// line-mode entry can redraw the idle prompt when it settles — the flow
  /// completes outside `_handleLine`, when the loop is parked reading the
  /// next line.
  Future<void>? _maybeStartFreshInstallProviderFlow() {
    if (!config.freshInstallProviderFlow || !io.isInteractive) return null;
    return _startProviderFlow();
  }

  /// The Edit/Delete picker for a custom provider entry.
  Future<void> _providerEditOrDelete(CustomProviderEntry entry) async {
    io.writeln('provider ${entry.name} (${entry.baseUrl})');
    final choice = await _pickOption('action', [
      ('edit', 'Edit provider', 'change base URL, name, key, or model'),
      ('delete', 'Delete provider', 'remove from the registry'),
    ]);
    if (choice == null) return;
    if (choice == 'delete') {
      await _deleteProviderWithConfirmation(entry);
      return;
    }
    _startProviderEditWizard(entry);
  }

  /// The edit wizard (prefilled from the entry when editing one, else from
  /// the active provider). The entry's own baseUrl/modelId/name MUST win
  /// over the live model — otherwise editing a non-active entry shows the
  /// wrong defaults (a kimi-active session editing the codemie entry would
  /// pre-fill Kimi's URL and model into the codemie wizard).
  void _startProviderEditWizard(CustomProviderEntry? entry) {
    final model = _agent.state.model;
    final spec = entry != null
        ? entry.spec
        : (resolveCliProviderSpec(model.provider) ??
              providerCatalog['openai']!);
    _startProviderFlow(
      initialType: entry?.apiType ?? spec.name,
      initialBaseUrl: entry?.baseUrl ?? model.baseUrl,
      initialName: entry?.name,
      initialModelId: entry?.modelId ?? model.id,
      editName: entry?.name,
      reauth: _editReauthOption(entry),
    );
  }

  /// The browser re-authorization choice for the edit wizard's key step:
  /// the same sign-in choice the connect flow offers, so the user can
  /// renew an expired credential without losing the entry. OpenRouter and
  /// CodeMie (any auth method — SSO entries as well as legacy entries
  /// whose `authMethod` was never recorded) get the picker; every other
  /// entry edits the key manually.
  ({String label, Future<String?> Function() run})? _editReauthOption(
    CustomProviderEntry? entry,
  ) {
    if (entry == null) return null;
    final orSpec = providerCatalog['openrouter'];
    if (orSpec != null &&
        (entry.apiType == 'openrouter' ||
            entry.baseUrl == orSpec.defaultBaseUrl)) {
      return (
        label: 'Browser OAuth (openrouter.ai)',
        run: _mintOpenRouterOAuthKey,
      );
    }
    // CodeMie: detected by the `/code-assistant-api/` URL marker — works
    // for legacy entries whose `authMethod` was never recorded too. The
    // picker still offers "Enter a new API key" for users who want to
    // paste a fresh cookie/JWT instead of opening the browser.
    if (entry.baseUrl.contains('/code-assistant-api/')) {
      return (label: 'Browser SSO (CodeMie)', run: _mintCodeMieSsoCookie);
    }
    return null;
  }

  /// Runs the browser OpenRouter OAuth flow and returns only the minted
  /// key: the edit wizard's own apply path persists it under the entry's
  /// key slot and switches, so the connect-time [_applyOpenRouterOAuthKey]
  /// (which stores + switches immediately) does not fit here.
  Future<String?> _mintOpenRouterOAuthKey() async {
    final exchangeFn =
        config.openRouterOAuthExchangeFn ?? _defaultOpenRouterExchange;
    final key = await runOpenRouterOAuthCliFlow(
      onStatus: io.writeln,
      exchangeFn: exchangeFn,
    );
    return key?.key;
  }

  /// Runs the CodeMie SSO login and returns only the freshly minted cookie
  /// string. Mirrors [_mintOpenRouterOAuthKey]: the edit wizard's own apply
  /// path persists it under the entry's key slot and switches, so the
  /// connect-time [_applyCodeMieSsoCredentials] (which also saves a
  /// registry entry and asks for a name) does not fit here.
  Future<String?> _mintCodeMieSsoCookie() async {
    final authenticate =
        config.codeMieSsoAuthenticateFn ??
        (url, onStatus) =>
            runCodeMieSsoCliFlow(codeMieUrl: url, onStatus: onStatus);
    final creds = await authenticate(defaultCodeMieBaseUrl, io.writeln);
    if (creds == null) return null;
    final cookie = creds.authToken;
    if (cookie.isEmpty) {
      io.writeln('CodeMie SSO carried no cookies — aborted');
      return null;
    }
    return cookie;
  }

  /// Deletes [entry] after a y/N confirmation.
  Future<void> _deleteProviderWithConfirmation(
    CustomProviderEntry entry,
  ) async {
    io.writeln(
      'Delete provider ${entry.name} (${entry.baseUrl}, model: ${entry.modelId})?',
    );
    final answer = await _pickOption('confirm delete', [
      ('y', 'Yes, delete', 'remove from the registry'),
      ('n', 'No, cancel', 'keep the provider'),
    ]);
    if (answer != 'y') return io.writeln('delete cancelled');
    await removeProvider(entry);
  }

  /// The flow's `/models` fetch with the same key resolution the provider
  /// switch uses (explicit token, else env → endpoint-scoped → legacy store).
  /// Failures answer an empty list: the flow falls back to manual entry.
  ///
  /// [mediaSlot] opts the fetch into catalog-side seeding — when set
  /// (e.g. `imageGeneration` for the image picker), the remote catalog's
  /// per-slot ids appear in the result even if `/v1/models` returns an
  /// empty list (which it always does for chat-only endpoints when
  /// picking image/video/tts/asr models).
  Future<List<String>> _fetchModelsForFlow(
    ProviderSpec spec,
    String baseUrl, {
    String? token,
    String? mediaSlot,
  }) async {
    final key = token ?? _providerKeyFor(spec, baseUrl) ?? '';
    try {
      final ids = await _fetchProviderModelIds(spec.name, baseUrl, key);
      if (mediaSlot == null) return ids;
      // For media slots the picker must show ONLY the media models —
      // the chat endpoint's `/v1/models` answer is noise (chat ids like
      // MiniMax-M3 don't generate images). mergeFor with a mediaSlot
      // parameter drops the chat list and answers exactly the
      // catalog's per-slot media ids.
      final merged = remoteCatalogEnrichment.mergeFor(
        (ids, const <String, int>{}, const <String, int>{}),
        spec.name,
        mediaSlot: [mediaSlot],
      );
      return merged.$1;
    } on Object {
      return const [];
    }
  }

  /// The shared model-list dispatch for the settings flows and the cache
  /// refresh: CodeMie endpoints list `/llm_models`, DIAL serves deployments
  /// (recording the reported limits), Copilot runs the token-exchange
  /// dialect (also recording the reported limits), everything else is an
  /// OpenAI-compatible `/models` ([AgentCliConfig.modelsFetcher] override
  /// included). Without this a DIAL/CodeMie pick dropped the user into
  /// manual model entry.
  Future<List<String>> _fetchProviderModelIds(
    String providerName,
    String baseUrl,
    String key,
  ) async {
    if (baseUrl.contains('/code-assistant-api/')) {
      return fetchCodeMieModels(baseUrl, key, client: config.modelsHttpClient);
    }
    if (providerName == 'dial') {
      return _fetchDialModelsAndFeatures(baseUrl, apiKey: key);
    }
    // Identity by kind, not a name literal (issue #772): the branch fires
    // for the catalog name AND the adapter kind.
    if (resolveCliProviderSpec(providerName)?.kind == 'chatgpt-codex') {
      final (ids, _, _) = await fetchModelsForEndpoint(
        baseUrl,
        apiKey: key,
        provider: 'chatgpt',
      );
      return ids;
    }
    if (providerName == 'copilot') {
      return _fetchCopilotModelsAndLimits(baseUrl, apiKey: key);
    }
    final fetch = config.modelsFetcher ?? _fetchOpenAiCompatibleModels;
    return fetch(baseUrl, apiKey: key);
  }

  /// Applies a completed wizard: writes/updates the registry entry (and the
  /// secure-store key under the entry's own key name), then switches the
  /// provider. In edit mode ([editName]) the entry keeps its name and
  /// its existing key when no new token was typed.
  Future<void> _applyCustomProviderSetup(
    CustomProviderSetup setup, {
    String? editName,
  }) async {
    final registry = config.customProviders;
    final modelId = setup.modelId.isNotEmpty
        ? setup.modelId
        : _agent.state.model.id;
    final token = setup.token;
    final keyName = await _persistSetupKey(setup, editName);
    // Edit mode keeps the existing entry's auth method (SSO/JWT routing
    // is the more precise signal than key format — set explicitly by the
    // connect flows). New entries default to api-key.
    final existingEntry = (editName != null && registry != null)
        ? registry.find(editName)
        : null;
    final entry = await _recordSetupEntry(
      setup,
      registry,
      modelId: modelId,
      keyName: keyName,
      editName: editName,
      existingEntry: existingEntry,
    );
    // The key for the switch: the freshly typed token, else the entry's
    // stored key, else the env resolution inside _switchProvider.
    final stored0 = entry?.keyName;
    final switchToken =
        token ?? (stored0 != null ? config.secureKeys?.read(stored0) : null);
    await _switchSetupEntry(
      setup,
      entry,
      modelId: modelId,
      keyName: keyName,
      switchToken: switchToken,
    );
  }

  /// The switch step of [_applyCustomProviderSetup]: CodeMie endpoints route
  /// through the cookie/JWT-specific helpers (the generic switch would send
  /// a cookie as `Authorization: Bearer`, which CodeMie rejects); everything
  /// else takes the regular switch.
  Future<void> _switchSetupEntry(
    CustomProviderSetup setup,
    CustomProviderEntry? entry, {
    required String modelId,
    required String? keyName,
    required String? switchToken,
  }) async {
    final stored = entry?.keyName;
    final isCodeMie = setup.baseUrl.contains('/code-assistant-api/');
    if (!isCodeMie || switchToken == null) {
      await _switchProvider(
        setup.spec,
        setup.baseUrl,
        modelId,
        token: switchToken,
        tokenKeyName: keyName,
      );
      return;
    }
    // For legacy entries whose `authMethod` was never recorded (defaults
    // to apiKey) we fall back to key-format detection — a JWT-shaped
    // value is a JWT, everything else is treated as a SSO cookie.
    final authMethod = entry?.authMethod ?? CustomProviderAuthMethod.apiKey;
    final looksJwt = isCodeMieJwtToken(switchToken);
    final asSso = authMethod == CustomProviderAuthMethod.sso || !looksJwt;
    if (asSso) {
      await _switchCodeMieProvider(
        setup.spec,
        setup.baseUrl,
        modelId,
        switchToken,
        stored ?? '',
      );
      return;
    }
    await _switchCodeMieJwtProvider(
      setup.spec,
      setup.baseUrl,
      modelId,
      switchToken,
      stored ?? '',
    );
  }

  /// The registry step of [_applyCustomProviderSetup]: writes (or renames
  /// on edit) the entry and returns it, or null without a registry.
  Future<CustomProviderEntry?> _recordSetupEntry(
    CustomProviderSetup setup,
    CustomProviderRegistry? registry, {
    required String modelId,
    required String? keyName,
    required String? editName,
    required CustomProviderEntry? existingEntry,
  }) async {
    if (registry == null) return null;
    // Renaming on edit: drop the old entry so the new name replaces it.
    if (editName != null && setup.name != editName) {
      registry.entries.removeWhere((e) => e.name == editName);
      io.writeln('renamed provider $editName to ${setup.name}');
    }
    final entry = CustomProviderEntry(
      name: setup.name,
      apiType: setup.spec.name,
      baseUrl: setup.baseUrl,
      modelId: modelId,
      keyName: keyName,
      authMethod: existingEntry?.authMethod ?? CustomProviderAuthMethod.apiKey,
    );
    // The wizard persists via its own switch-time fire (below); only the
    // extension flows use the persisting variant of the shared helper.
    await _saveCustomProviderEntry(entry, persist: false);
    if (editName == null) {
      io.writeln('saved provider ${entry.name} (listed first in /provider)');
    }
    return entry;
  }

  /// The registry-append seam shared by the custom wizard
  /// ([_recordSetupEntry]) and the extension provider flows: adds [entry]
  /// and marks it the active custom provider. [persist] additionally
  /// notifies [AgentCliConfig.onProviderChanged] — the callback the
  /// executable persists the `customProviders:` config section on — which
  /// only the extension flows need (the wizard fires at switch time).
  Future<void> _saveCustomProviderEntry(
    CustomProviderEntry entry, {
    bool persist = true,
  }) async {
    final registry = config.customProviders;
    if (registry == null) return;
    registry.add(entry);
    _activeCustomName = entry.name;
    if (persist) {
      await config.onProviderChanged?.call(_providerKind, _apiKey);
    }
  }

  /// The key-name/persistence step of [_applyCustomProviderSetup]: returns
  /// the secure-store key name the entry should carry, or null when no key

[2258 more lines in file. Use offset=401 to continue.]

  /// the secure-store key name the entry should carry, or null when no key
  /// persists (keyless, session-only, or a failed/unavailable store).
  /// Without a fresh token the edit keeps the entry's existing key name.
  Future<String?> _persistSetupKey(
    CustomProviderSetup setup,
    String? editName,
  ) async {
    final registry = config.customProviders;
    final token = setup.token;
    if (token == null) {
      return editName != null ? registry?.find(editName)?.keyName : null;
    }
    final keyName = _setupKeyName(setup, editName);
    final keys = config.secureKeys;
    if (keys != null && keys.available) {
      await keys.save(keyName, token);
      config.onSecretStored?.call(keyName, token);
      return keyName;
    }
    // No secure store OR the write failed (locked/managed keychain):
    // the key still applies to this session via the switch below, but
    // cannot persist with the entry.
    io.writeln(
      'could not save the key to the secure store (unavailable, locked, '
      'or managed) — it applies to this session only and is not saved '
      'with the provider',
    );
    return null;
  }

  /// The secure-store key name a setup entry should carry: a same-name edit
  /// keeps the entry's existing store name (stable key slot); a new entry
  /// (or a rename) gets a NAME-scoped one, so several accounts on the same
  /// endpoint keep separate keys instead of overwriting one host-scoped
  /// entry.
  String _setupKeyName(CustomProviderSetup setup, String? editName) {
    final keyName = _reusedSetupEntry(setup, editName)?.keyName;
    return keyName ??
        CustomProviderRegistry.keyNameFor(
          setup.baseUrl,
          providerName: setup.name,
        );
  }

  /// The saved entry whose store key a setup edit reuses: only a same-name
  /// edit of an existing entry (a rename is a new key slot).
  CustomProviderEntry? _reusedSetupEntry(
    CustomProviderSetup setup,
    String? editName,
  ) {
    if (editName == null || setup.name != editName) return null;
    return config.customProviders?.find(editName);
  }

  /// Switches to a saved registry entry (picker or typed `/provider <name>`):
  /// restores its last-used model and marks it active. CodeMie endpoints
  /// (detected by the `/code-assistant-api/` URL marker) are routed to
  /// [_switchToSavedCodeMieProvider], which distinguishes SSO cookie auth from
  /// JWT Bearer auth; other entries use the regular provider switch.
  Future<void> _switchToSavedProvider(CustomProviderEntry entry) async {
    if (entry.baseUrl.contains('/code-assistant-api/')) {
      await _switchToSavedCodeMieProvider(entry);
      return;
    }
    final keyName = entry.keyName;
    final token = keyName != null ? config.secureKeys?.read(keyName) : null;
    _activeCustomName = entry.name;
    await _switchProvider(
      entry.spec,
      entry.baseUrl,
      entry.modelId,
      token: token,
      tokenKeyName: keyName,
      authHeader: entry.authHeader,
    );
  }

  /// Per-provider model memory: while a saved custom provider is active, a
  /// `/model` switch rewrites the entry's last-used model (the host persists
  /// it with the usual config save).
  Future<void> _recordCustomModel(String modelId) async {
    final active = _activeCustomName;
    if (active != null) {
      config.customProviders?.updateModel(active, modelId);
    }
    // ALWAYS notify the host, not just with an active custom entry: the
    // host persists the live model id + baseUrl, and without this a
    // catalog-provider `/model` switch (active == null) would save nothing
    // — the next start restored the last provider switch's model instead
    // of the one the user picked.
    await config.onModelChanged?.call(_agent.state.model);
  }

  /// The TUI provider picker (bare `/provider`): saved custom providers
  /// first, then the catalog presets, then the `+ Add provider` wizard
  /// entry last. A saved selection restores the entry's last-used model.
  /// The TUI provider picker (bare `/provider`): saved providers only,
  /// plus `+ Add provider` as the last entry. Selecting a saved provider
  /// opens its Edit/Delete sub-picker; selecting add opens the preset
  /// picker. No catalog presets shown — they are only reachable from the
  /// add flow.
  void _openProviderPicker() {
    final items = <MenuItem>[
      ..._savedProviderItems(),
      ..._extProviderItems(),
      const MenuItem(
        key: 'add',
        label: '+ Add provider',
        description: 'openrouter, chatgpt, codemie, openai, ...',
      ),
    ];
    _tuiController?.openPicker('provider', 'Providers', items);
  }

  /// The picker's saved-custom-provider entries (registry order), each
  /// marked `(current)` when it is the active one.
  Iterable<MenuItem> _savedProviderItems() {
    final registry = config.customProviders;
    if (registry == null) return const [];
    return [for (final entry in registry.entries) _savedProviderItem(entry)];
  }

  /// One picker entry for a saved custom provider, marked `(current)` when
  /// it is the active one.
  MenuItem _savedProviderItem(CustomProviderEntry entry) => MenuItem(
    key: 'saved:${entry.name}',
    label: entry.name,
    description:
        '${entry.baseUrl} · ${entry.modelId}'
        '${entry.name == _activeCustomName ? ' (current)' : ''}',
  );

  /// `/provider [name] [baseUrl] [token] | custom` — shows the active
  /// provider, endpoint, and key status plus the supported catalog; switches
  /// the provider/endpoint at runtime; or starts the guided custom-provider
  /// setup (`custom`, see provider_flow.dart). A saved provider name
  /// (registry) restores its last-used model. Without an explicit token the
  /// key resolves from the provider's catalog env names; a custom endpoint
  /// may run keyless (local servers). The executable persists
  /// provider/model/baseUrl but never the key itself.
  Future<void> _handleProviderCommand(String rest) async {
    final args = rest
        .split(RegExp(r'\s+'))
        .where((part) => part.isNotEmpty)
        .toList();
    if (args.isEmpty) {
      _printProviderStatus();
      return;
    }
    if (_dispatchProviderSubcommand(args)) return;
    if (args.length > 3) {
      io.writeln('usage: /provider <name> [baseUrl] [token]');
      return;
    }
    // A saved custom provider name resolves before the catalog. Reserved
    // catalog names are enforced away from the registry (rejected at
    // `add` and the name prompts, dropped at load and merged writes —
    // #221/#706), so a saved name never shadows a catalog route; alias
    // spellings (`chatgpt.com`) resolve onto their canonical record.
    final saved = args.length == 1
        ? config.customProviders?.find(args[0])
        : null;
    if (saved != null) {
      try {
        await _switchToSavedProvider(saved);
      } on Object catch (error) {
        io.writeln('provider switch failed: $error');
      }
      return;
    }
    // Extension flows (AC5): namespaced `ext:<name>:<id>` keys, checked
    // AFTER the saved lookup — core entries always win on bare ids (E10;
    // by construction a flow key never equals one).
    if (args.length == 1 && args.first.startsWith('ext:')) {
      _startExtProviderFlow(args.first);
      return;
    }
    try {
      await _switchToCatalogProvider(args);
    } on Object catch (error) {
      io.writeln('provider switch failed: $error');
    }
  }

  /// Dispatches the subcommand forms of `/provider` (custom, openrouter
  /// oauth, chatgpt oauth, copilot connect, codemie sso, dial setup).
  /// Returns true when one handled it.
  bool _dispatchProviderSubcommand(List<String> args) {
    if (_startAiinArg(args)) return true;
    if (_startCustomProviderArg(args)) return true;
    if (_startOpenRouterArg(args)) return true;
    if (_startChatGptOAuthArg(args)) return true;
    if (_startCopilotArg(args)) return true;
    if (_startCodeMieArg(args)) return true;
    if (_startDialSetupArg(args)) return true;
    if (_startKimiArg(args)) return true;
    return false;
  }

